169			// per-harness SessionStart surfaces the *index* content. So the mock merger
170			// writes preferences directly into MEMORY.md.
171			const dreamResult = await dream({
172				merger: async () => ({
173					files: [
174						{
175							path: "profile/MEMORY.md",
176							frontmatter: {
177								source_event_ids: signalIds,
178								title: "Preferences",
179								type: "note",
180								permalink: "profile/MEMORY",
181								scope: "profile",
182								last_dreamed_at: new Date().toISOString(),
183								confidence: 0.95,
184							},
185							markdown:
186								"# Preferences\n\n- Prefers **concise commit messages**.\n- Use ASCII dashes only in docs.\n",
187						},
188						{
189							path: "project/demo/MEMORY.md",
190							frontmatter: {
191								source_event_ids: signalIds,
192								title: "demo — decisions",
193								type: "note",
194								permalink: "project/demo/MEMORY",
195								scope: "project",
196								project: "demo",
197								last_dreamed_at: new Date().toISOString(),
198								confidence: 0.9,
199							},
200							markdown: "# demo decisions\n\n- README.md is the canonical entry point.\n",
201						},
202					],
203					consumed_event_ids: signalIds,
204				}),
205				skipReindex: true, // sandbox vault has no qmd collection
206			});
207			expect(dreamResult.status).toBe("ok");
208			expect(dreamResult.filesAccepted).toBe(2);
209	
210			// --- Step 3: a *Claude Code* SessionStart in the same repo ----------
211			const claudeR = await dispatch({
212				client: "claude",
213				sessionId: "claude-cross-A",
214				cwd,
215				eventType: "SessionStart",
216				payload: { source: "startup" },
217			});
218			expect(claudeR.timedOut).toBe(false);
219			expect(claudeR.stdout).toContain("Prefers **concise commit messages**");
220			expect(claudeR.stdout).toContain("ASCII dashes only");
221			expect(claudeR.stdout).toContain("README.md is the canonical entry point");
222	
223			// --- Step 4: a *Codex* SessionStart in the same repo ----------------
224			const codexR = await dispatch({
225				client: "codex",
226				sessionId: "codex-cross-A",
227				cwd,
228				eventType: "SessionStart",
229				payload: { source: "startup" },
230			});
231			expect(codexR.timedOut).toBe(false);
232			expect(codexR.stdout).toContain("Prefers **concise commit messages**");
233			expect(codexR.stdout).toContain("README.md is the canonical entry point");
