235			// --- Step 5: a fresh Pi session: first before_agent_start NOW ------
236			// surfaces the persistent-memory in the systemPrompt return.
237			const piB = mockPi(cwd);
238			register(piB.api, { sessionId: "pi-cross-B", cwd });
239			await piB.handlers.session_start!({ type: "session_start", reason: "startup" }, piB.ctx);
240			const ret = await piB.handlers.before_agent_start!(bas("any prompt", "BASE_B"), piB.ctx);
241			expect(ret).toBeDefined();
242			const sp = (ret as { systemPrompt?: string }).systemPrompt;
243			expect(sp).toBeDefined();
244			expect(sp!).toContain("<persistent-memory>");
245			expect(sp!).toContain("Prefers **concise commit messages**");
