248			const ret2 = await piB.handlers.before_agent_start!(bas("follow-up", "BASE_B"), piB.ctx);
249			if (ret2) {
250				expect((ret2 as Record<string, unknown>).systemPrompt).toBeUndefined();
251			}
252		});
