/**
 * cross-harness-smoke.spec.ts — deliverable 7, redone against real Pi API.
 *
 * End-to-end loop: a Pi session captures decisions -> dream phase merges
 * them into the canonical wiki -> a Claude Code SessionStart and a Codex
 * SessionStart in the same repo both surface those memories.
 *
 * The Pi step uses the in-process extension wired against the REAL pi.on(...)
 * event-bus API. Claude + Codex go through the SAME dispatcher the shell
 * wrappers use (`harness-cli.dispatch`).
 */

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import register, { type ExtensionAPI } from "../src/extension.ts";
import type {
	BeforeAgentStartEvent,
	BeforeAgentStartEventResult,
	ExtensionContext,
	ExtensionHandler,
	SessionShutdownEvent,
	SessionStartEvent,
	ToolCallEvent,
	ToolResultEvent,
} from "@valkyriweb/pi-coding-agent";

type HandlerMap = {
	session_start?: ExtensionHandler<SessionStartEvent>;
	before_agent_start?: ExtensionHandler<BeforeAgentStartEvent, BeforeAgentStartEventResult>;
	tool_call?: ExtensionHandler<ToolCallEvent, unknown>;
	tool_result?: ExtensionHandler<ToolResultEvent, unknown>;
	session_shutdown?: ExtensionHandler<SessionShutdownEvent>;
};

function bas(prompt: string, systemPrompt: string): BeforeAgentStartEvent {
	return {
		type: "before_agent_start",
		prompt,
		systemPrompt,
		systemPromptOptions: {} as BeforeAgentStartEvent["systemPromptOptions"],
		source: "interactive",
	};
}
import { dispatch } from "../src/harness-cli.ts";
import { dream } from "../src/dream/dream.ts";
import { memoryDir, wikiRoot } from "../src/store.ts";

let scratch: string;

beforeEach(async () => {
	scratch = await mkdtemp(join(tmpdir(), "dream-smoke-"));
	process.env.DREAM_EVENTS_HOME = join(scratch, "events-root");
	process.env.DREAM_WIKI_HOME = join(scratch, "wiki-root");
	await mkdir(join(memoryDir(), "profile"), { recursive: true });
	await mkdir(join(memoryDir(), "project", "demo"), { recursive: true });
	const vault = wikiRoot();
	const env = { ...process.env, GIT_AUTHOR_NAME: "smoke", GIT_AUTHOR_EMAIL: "smoke@local" };
	spawnSync("git", ["init", "-q"], { cwd: vault, env });
	spawnSync(
		"git",
		[
			"-c",
			"user.email=smoke@local",
			"-c",
			"user.name=smoke",
			"commit",
			"-q",
			"--allow-empty",
			"-m",
			"init",
		],
		{ cwd: vault, env },
	);
});

afterEach(async () => {
	delete process.env.DREAM_EVENTS_HOME;
	delete process.env.DREAM_WIKI_HOME;
	await rm(scratch, { recursive: true, force: true });
});

function mockPi(cwd: string): { api: ExtensionAPI; handlers: HandlerMap; ctx: ExtensionContext } {
	const handlers: HandlerMap = {};
	const api = {
		on(event: string, handler: unknown) {
			(handlers as Record<string, unknown>)[event] = handler;
		},
		registerMessageRenderer() {},
		registerCommand() {},
		registerShortcut() {},
		registerTool() {},
	} as unknown as ExtensionAPI;
	const ctx = {
		cwd,
		hasUI: false,
		ui: { setStatus() {}, notify() {}, theme: { fg: (_k: string, s: string) => s } },
	} as unknown as ExtensionContext;
	return { api, handlers, ctx };
}

describe("cross-harness smoke — Pi → dream → Claude/Codex SessionStart", () => {
	it("Pi captures decisions, dream merges them, Claude + Codex SessionStart both surface them", async () => {
		const cwd = join(scratch, "demo-repo");
		await mkdir(cwd, { recursive: true });
		await writeFile(join(cwd, ".dream-memory.yml"), "project_slug: demo\n");

		// --- Step 1: a Pi session captures decisions + tool events ----------
		const piA = mockPi(cwd);
		register(piA.api, { sessionId: "pi-cross-A", cwd });

		// session_start fires first — notification only, also appends a
		// SessionStart event for dream's audit trail.
		await piA.handlers.session_start!({ type: "session_start", reason: "startup" }, piA.ctx);

		// FIRST before_agent_start: empty vault, so persistent-memory is
		// empty → handler returns void (no systemPrompt mutation).
		const firstRet = await piA.handlers.before_agent_start!(
			bas("I prefer concise commit messages.", "BASE"),
			piA.ctx,
		);
		expect(firstRet).toBeUndefined();

		// Tool round-trip + shutdown — these all appendEvent.
		await piA.handlers.tool_call!(
			{
				type: "tool_call",
				toolName: "edit",
				toolCallId: "c1",
				input: { path: "README.md", note: "use ascii dashes only" },
			},
			piA.ctx,
		);
		await piA.handlers.tool_result!(
			{
				type: "tool_result",
				toolName: "edit",
				toolCallId: "c1",
				input: {},
				content: [{ type: "text", text: "ok" }],
				isError: false,
				details: undefined,
			} as ToolResultEvent,
			piA.ctx,
		);
		await piA.handlers.session_shutdown!({ type: "session_shutdown", reason: "quit" }, piA.ctx);

		// --- Step 2: dream phase merges the events into canonical memory ----
		const eventsFile = join(scratch, "events-root", "events", "pi-cross-A.jsonl");
		expect(existsSync(eventsFile)).toBe(true);
		const lines = (await readFile(eventsFile, "utf8")).trim().split("\n");
		const allEvents = lines.map((l) => JSON.parse(l) as { event_id: string; event_type: string });
		const allIds = allEvents.map((e) => e.event_id);
		// Noise types are filtered before the merger sees them; mock merger must only cite signal IDs.
		// Keep in sync with DEFAULT_NOISE_TYPES in src/dream/dream.ts.
		const NOISE = new Set(["PreToolUse", "PostToolUse", "RecallInjected", "ActiveRecallInjected",
			"RecallSkipped", "QmdUnhealthy", "MemoryInjectionTimeout", "SessionStart", "Stop"]);
		const signalIds = allEvents.filter((e) => !NOISE.has(e.event_type)).map((e) => e.event_id);
		expect(allIds.length).toBeGreaterThanOrEqual(3);

		// Index-only auto-inject contract (store.ts a0f290f): only profile/MEMORY.md
		// and project/<slug>/MEMORY.md are auto-loaded into SessionStart. Topic files
		// like profile/preferences.md still get written by the real dream agent (for
		// memory_search discovery), but the cross-harness assertion here is that the
		// per-harness SessionStart surfaces the *index* content. So the mock merger
		// writes preferences directly into MEMORY.md.
		const dreamResult = await dream({
			merger: async () => ({
				files: [
					{
						path: "profile/MEMORY.md",
						frontmatter: {
							source_event_ids: signalIds,
							title: "Preferences",
							type: "note",
							permalink: "profile/MEMORY",
							scope: "profile",
							last_dreamed_at: new Date().toISOString(),
							confidence: 0.95,
						},
						markdown:
							"# Preferences\n\n- Prefers **concise commit messages**.\n- Use ASCII dashes only in docs.\n",
					},
					{
						path: "project/demo/MEMORY.md",
						frontmatter: {
							source_event_ids: signalIds,
							title: "demo — decisions",
							type: "note",
							permalink: "project/demo/MEMORY",
							scope: "project",
							project: "demo",
							last_dreamed_at: new Date().toISOString(),
							confidence: 0.9,
						},
						markdown: "# demo decisions\n\n- README.md is the canonical entry point.\n",
					},
				],
				consumed_event_ids: signalIds,
			}),
			skipReindex: true, // sandbox vault has no qmd collection
		});
		expect(dreamResult.status).toBe("ok");
		expect(dreamResult.filesAccepted).toBe(2);

		// --- Step 3: a *Claude Code* SessionStart in the same repo ----------
		const claudeR = await dispatch({
			client: "claude",
			sessionId: "claude-cross-A",
			cwd,
			eventType: "SessionStart",
			payload: { source: "startup" },
		});
		expect(claudeR.timedOut).toBe(false);
		expect(claudeR.stdout).toContain("Prefers **concise commit messages**");
		expect(claudeR.stdout).toContain("ASCII dashes only");
		expect(claudeR.stdout).toContain("README.md is the canonical entry point");

		// --- Step 4: a *Codex* SessionStart in the same repo ----------------
		const codexR = await dispatch({
			client: "codex",
			sessionId: "codex-cross-A",
			cwd,
			eventType: "SessionStart",
			payload: { source: "startup" },
		});
		expect(codexR.timedOut).toBe(false);
		expect(codexR.stdout).toContain("Prefers **concise commit messages**");
		expect(codexR.stdout).toContain("README.md is the canonical entry point");

		// --- Step 5: a fresh Pi session: first before_agent_start NOW ------
		// surfaces the persistent-memory in the systemPrompt return.
		const piB = mockPi(cwd);
		register(piB.api, { sessionId: "pi-cross-B", cwd });
		await piB.handlers.session_start!({ type: "session_start", reason: "startup" }, piB.ctx);
		const ret = await piB.handlers.before_agent_start!(bas("any prompt", "BASE_B"), piB.ctx);
		expect(ret).toBeDefined();
		const sp = (ret as { systemPrompt?: string }).systemPrompt;
		expect(sp).toBeDefined();
		expect(sp!).toContain("<persistent-memory>");
		expect(sp!).toContain("Prefers **concise commit messages**");
		// Cache safety: a SECOND before_agent_start in same session must NOT
		// also return systemPrompt.
		const ret2 = await piB.handlers.before_agent_start!(bas("follow-up", "BASE_B"), piB.ctx);
		if (ret2) {
			expect((ret2 as Record<string, unknown>).systemPrompt).toBeUndefined();
		}
	});
