/**
 * Storage backend for dream-memory-harness.
 *
 * Two roots, locked by GOAL DECISIONS (REVIEW A1/D4):
 *   events: ~/.dream-memory/events/  (raw append-only JSONL, never edited)
 *   wiki:   ~/obsidian/dream-memory/memory/  (basic-memory project)
 *
 * Surface (deliverable 2):
 *   appendEvent / readEventsSince
 *   readMemoryTree (24kB / 8-file SessionStart-budget aware)
 *   searchMemory (shells `bm tool search-notes --hybrid`, timeout-bounded)
 *   readWatermark / writeWatermark (atomic via tmp + rename)
 *   resolveProjectSlug (.dream-memory.yml -> git remote -> basename)
 */

import { spawn } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import {
	appendFile,
	mkdir,
	open,
	readFile,
	readdir,
	rename,
	stat,
	writeFile,
} from "node:fs/promises";
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { basename, dirname, isAbsolute, join, relative, resolve } from "node:path";
import { ulid } from "ulid";

import { redact, type RedactionHit } from "./redact.js";
import {
	probeQmdHealth,
	isTransientSqliteRace,
	QMD_UNHEALTHY_ERROR_PREFIX,
	type QmdHealth,
} from "./qmd-health.ts";
// Lazy-load telemetry to avoid pulling opik → ai-sdk → js-tiktoken at boot.
let _stTelModule: Promise<typeof import("./telemetry.ts")> | null = null;
function getSTel() {
	if (!_stTelModule) _stTelModule = import("./telemetry.ts");
	return _stTelModule;
}

// ---------------------------------------------------------------------------
// Roots — read env at call time so tests can swap homes per spec.

export function eventsRoot(): string {
	return process.env.DREAM_EVENTS_HOME ?? join(homedir(), ".dream-memory");
}

export function wikiRoot(): string {
	return process.env.DREAM_WIKI_HOME ?? join(homedir(), "obsidian", "dream-memory");
}

export function eventsDir(): string {
	return join(eventsRoot(), "events");
}

export function memoryDir(): string {
	return join(wikiRoot(), "memory");
}

// ---------------------------------------------------------------------------
// Inbox memtable — agent-writable, immediately searchable/injectable.
//
// Locked by the always-on-ingestion goal:
//   - Single file `memory/inbox/notes.md` (one entry per `## <ulid>` block)
//     so qmd indexes it without per-note churn.
//   - 64 kB / 200-entry soft cap; on overflow, ALL current entries are
//     atomically moved to `inbox-overflow.md` so memory_note never blocks.
//   - rewriteInbox(keep_event_ids) is the dream phase's only way to
//     evict a consolidated entry; atomic via tmp + rename.
//   - All entry text is redact()'d before append (defence in depth — events
//     are also redacted on the first stage write).

export const INBOX_MAX_BYTES = 64 * 1024;
export const INBOX_MAX_ENTRIES = 200;
const INBOX_DIR = "inbox";
const INBOX_FILE = "notes.md";
const INBOX_OVERFLOW_FILE = "inbox-overflow.md";

export function inboxDir(): string {
	return join(memoryDir(), INBOX_DIR);
}
export function inboxNotesPath(): string {
	return join(inboxDir(), INBOX_FILE);
}
export function inboxOverflowPath(): string {
	return join(inboxDir(), INBOX_OVERFLOW_FILE);
}

export function watermarkPath(): string {
	return join(eventsRoot(), "watermark.json");
}

export function slugMapPath(): string {
	return join(eventsRoot(), "slug-map.json");
}

async function ensureDirs(): Promise<void> {
	await mkdir(eventsDir(), { recursive: true });
	for (const sub of ["profile", "project", "tools", "inbox"]) {
		await mkdir(join(memoryDir(), sub), { recursive: true });
	}
}

// ---------------------------------------------------------------------------
// Event types

export type EventType =
	| "SessionStart"
	| "UserPromptSubmit"
	| "PreToolUse"
	| "PostToolUse"
	| "Stop"
	/**
	 * Explicit durable note captured live by the Pi `memory_note` tool.
	 * Payload shape:
	 *   text:       string — concise durable fact/decision/preference/lesson
	 *   source:     "tool" | string
	 *   tool_call_id?: string
	 *
	 * AgentNote is intentionally an event only. The dream phase remains the
	 * sole writer to canonical memory markdown.
	 */
	| "AgentNote"
	| "MemoryInjectionTimeout"
	/**
	 * Emitted (fire-and-forget) whenever memory is successfully injected into
	 * a session turn. Payload shape:
	 *   where:        "SessionStart" | "UserPromptSubmit"
	 *   bytes:        number   — byte length of injected block
	 *   latency_ms:   number   — wall time from query start to stdout ready
	 *   qmd:          { state: "ok"|"unhealthy"|"timeout"|"error"|"skipped", hits: number, permalinks: string[] }
	 */
	| "RecallInjected"
	/**
	 * Emitted (fire-and-forget) by runActiveRecall() after the haiku LLM call.
	 * Payload shape:
	 *   result:      "injected" | "none" | "error" | "timeout" | "breaker"
	 *   model:       string    — provider/id used
	 *   latency_ms:  number
	 *   hits_fetched: number   — total hits pre-fetched from qmd
	 *   hits_used:   number    — non-zero only when result=injected
	 *   bytes:       number    — byte length of injected content (0 when none)
	 *   tokens_in:   number
	 *   tokens_out:  number
	 *   qmd:         { state, hits }
	 */
	| "ActiveRecallInjected"
	| string;

export type AppendEventInput = {
	sessionId: string;
	client: "pi" | "claude" | "codex" | string;
	cwd: string;
	projectSlug: string;
	eventType: EventType;
	payload?: Record<string, unknown>;
};

export type Event = {
	event_id: string; // ULID, monotonic per-process
	session_id: string;
	client: string;
	cwd: string;
	project_slug: string;
	ts: string; // ISO8601, advisory only — watermarks use event_id
	event_type: EventType;
	payload: Record<string, unknown>;
	payload_hash: string; // sha256(canonical JSON of redacted payload)
	redaction_hits: RedactionHit[];
};

// ---------------------------------------------------------------------------
// appendEvent — never throws past a logged error

function canonicalJSON(value: unknown): string {
	// Deterministic key order so payload_hash is stable.
	const seen = new WeakSet();
	const sort = (v: unknown): unknown => {
		if (v && typeof v === "object") {
			if (seen.has(v as object)) return null;
			seen.add(v as object);
			if (Array.isArray(v)) return v.map(sort);
			return Object.fromEntries(
				Object.keys(v as Record<string, unknown>)
					.sort()
					.map((k) => [k, sort((v as Record<string, unknown>)[k])]),
			);
		}
		return v;
	};
	return JSON.stringify(sort(value));
}

export async function appendEvent(input: AppendEventInput): Promise<Event | null> {
	// Snapshot the events dir synchronously, before any await. appendEvent is
	// almost always fire-and-forget (`void appendEvent(...)`), so resolving the
	// path after an await let a late flush re-read DREAM_EVENTS_HOME — which in
	// tests is unset during teardown, leaking events into the real ~/.dream-memory.
	// Binding the dir at call time pins the write to the env state the caller saw.
	const dir = eventsDir();
	try {
		await mkdir(dir, { recursive: true });
		const payload = input.payload ?? {};
		const { value: redactedPayload, hits } = redact(payload);
		const event: Event = {
			event_id: ulid(),
			session_id: input.sessionId,
			client: input.client,
			cwd: input.cwd,
			project_slug: input.projectSlug,
			ts: new Date().toISOString(),
			event_type: input.eventType,
			payload: redactedPayload as Record<string, unknown>,
			payload_hash: createHash("sha256").update(canonicalJSON(redactedPayload)).digest("hex"),
			redaction_hits: hits,
		};
		const line = JSON.stringify(event) + "\n";
		const path = join(dir, `${input.sessionId}.jsonl`);
		const handle = await open(path, "a");
		try {
			await handle.appendFile(line);
			await handle.datasync();
		} finally {
			await handle.close();
		}
		return event;
	} catch (err) {
		// Never throw past appendEvent — hooks must not block the harness.
		console.error("[dream-memory] appendEvent failed:", err);
		return null;
	}
}

// ---------------------------------------------------------------------------
// Inbox — appendInboxNote / readInbox / rewriteInbox.
//
// Single-file memtable. Per-entry shape:
//   ## <ulid>
//   <!-- event_id: 01K... session: ... ts: ... slug: ... -->
//   <text>
//
// followed by a blank line. Plain markdown so qmd indexes it as-is.

export type AppendInboxNoteInput = {
	event_id: string;
	session_id: string;
	slug: string;
	text: string;
	/** ISO8601 timestamp; defaults to now. */
	ts?: string;
};

export type InboxEntry = {
	event_id: string;
	session_id: string;
	slug: string;
	ts: string;
	text: string;
	/** Rendered block (header + comment + text + trailing blank line). */
	raw: string;
};

function renderInboxBlock(input: { event_id: string; session_id: string; slug: string; ts: string; text: string }): string {
	// Trim trailing blank lines from text but keep internal newlines.
	const body = input.text.replace(/\s+$/, "");
	return (
		`## ${input.event_id}\n` +
		`<!-- event_id: ${input.event_id} session: ${input.session_id} ts: ${input.ts} slug: ${input.slug} -->\n` +
		`${body}\n\n`
	);
}

function parseInboxText(text: string): InboxEntry[] {
	if (!text || !text.trim()) return [];
	const out: InboxEntry[] = [];
	// Split on `## ` at line start; keep delimiters with each chunk via lookahead.
	const chunks = text.split(/(?=^## )/m).filter((c) => c.trim().length > 0);
	for (const chunk of chunks) {
		const headerMatch = /^## (\S+)\s*\n<!--\s*event_id:\s*(\S+)\s+session:\s*(\S+)\s+ts:\s*(\S+)\s+slug:\s*(\S+)\s*-->\s*\n([\s\S]*?)$/m.exec(chunk);
		if (!headerMatch) continue;
		const [, , eventId, sessionId, ts, slug, rawBody] = headerMatch;
		const body = rawBody!.replace(/\s+$/, "");
		out.push({
			event_id: eventId!,
			session_id: sessionId!,
			ts: ts!,
			slug: slug!,
			text: body,
			raw: renderInboxBlock({
				event_id: eventId!,
				session_id: sessionId!,
				slug: slug!,
				ts: ts!,
				text: body,
			}),
		});
	}
	return out;
}

/**
 * Process-local mutex: serialise concurrent appendInboxNote() calls so
 * the rendered blocks never interleave on disk. O_APPEND guarantees
 * atomic writes only up to PIPE_BUF (~4kB on Linux/macOS); a serialised
 * chain is the cheapest belt-and-braces.
 */
let inboxAppendChain: Promise<unknown> = Promise.resolve();

async function ensureInboxDir(): Promise<void> {
	await mkdir(inboxDir(), { recursive: true });
}

/**
 * Spill ALL current notes.md entries to inbox-overflow.md (atomic append)
 * and reset notes.md to empty when the cap is hit. Keeps `memory_note`
 * non-blocking under heavy churn while preserving searchability — the
 * overflow file lives under `memory/inbox/` and stays in qmd's index.
 *
 * Called from inside the appendInboxNote serialised chain so it observes
 * a consistent file size.
 */
async function spillIfNeeded(): Promise<void> {
	const path = inboxNotesPath();
	if (!existsSync(path)) return;
	const text = await readFile(path, "utf8");
	if (!text) return;
	const bytes = Buffer.byteLength(text, "utf8");
	const entries = parseInboxText(text);
	if (bytes < INBOX_MAX_BYTES && entries.length < INBOX_MAX_ENTRIES) return;

	const overflow = await open(inboxOverflowPath(), "a");
	try {
		const toAppend = text.endsWith("\n") ? text : `${text}\n`;
		await overflow.appendFile(toAppend);
		await overflow.datasync();
	} finally {
		await overflow.close();
	}
	const tmp = `${path}.tmp.${randomBytes(6).toString("hex")}`;
	await writeFile(tmp, "");
	await rename(tmp, path);
}

/**
 * Append a memory note to `memory/inbox/notes.md`. Same redact() pass
 * that runs in appendEvent. Returns the rendered block on success.
 *
 * Failures are caught and re-thrown so the caller can log a breadcrumb;
 * the tool handler in extension.ts MUST swallow this so the live event
 * log remains the audit trail of record (D5).
 */
export async function appendInboxNote(input: AppendInboxNoteInput): Promise<string> {
	const ts = input.ts ?? new Date().toISOString();
	const { value: redactedText } = redact(input.text);
	const block = renderInboxBlock({
		event_id: input.event_id,
		session_id: input.session_id,
		slug: input.slug,
		ts,
		text: redactedText,
	});

	const task = inboxAppendChain.then(async () => {
		await ensureInboxDir();
		await spillIfNeeded();
		const handle = await open(inboxNotesPath(), "a");
		try {
			await handle.appendFile(block);
			await handle.datasync();
		} finally {
			await handle.close();
		}
		// Record inbox size gauges for SigNoz (post-write, background).
		try {
			const sizeBytes = await inboxSizeBytes();
			const entries = await readInbox();
			void getSTel().then(({ recordGauge }) => {
				recordGauge("dream_memory.inbox.size_bytes", sizeBytes);
				recordGauge("dream_memory.inbox.entries", entries.length);
			});
		} catch {
			// gauge recording must never block or throw
		}
	});
	// Keep the chain alive even if this task fails — a single broken append
	// must not poison every subsequent caller.
	inboxAppendChain = task.catch(() => undefined);
	await task;
	return block;
}

/** Read all entries from `memory/inbox/notes.md` in original (append) order. */
export async function readInbox(): Promise<InboxEntry[]> {
	const path = inboxNotesPath();
	if (!existsSync(path)) return [];
	const text = await readFile(path, "utf8");
	return parseInboxText(text);
}

/**
 * Atomically rewrite `memory/inbox/notes.md` keeping ONLY entries whose
 * event_id is in `keepEventIds`. Order is preserved. Used by the dream
 * phase after a successful canonical write + reindex (D4).
 */
export async function rewriteInbox(keepEventIds: Set<string>): Promise<void> {
	const path = inboxNotesPath();
	if (!existsSync(path)) return;
	await ensureInboxDir();
	const text = await readFile(path, "utf8");
	const entries = parseInboxText(text);
	const kept = entries.filter((e) => keepEventIds.has(e.event_id));
	const body = kept.map((e) => e.raw).join("");
	const tmp = `${path}.tmp.${randomBytes(6).toString("hex")}`;
	await writeFile(tmp, body);
	await rename(tmp, path);
}

/**
 * Cheap keyword/recency search over inbox entries. Used by the
 * UserPromptSubmit injection path so notes captured *this session* are
 * recoverable BEFORE qmd reindex runs (the latency cliff fix).
 *
 * Scoring: `score = sum(query tokens ∩ entry text tokens)`. Tokens are
 * whitespace-split, lowercased, length >= 3 (cheap stopword filter).
 * Entries with score > 0 sort by score desc; ties break by recency.
 * If no entry scores, fall back to the N most-recent entries so the agent
 * still sees the freshest capture (preferable to silence on near-misses).
 */
export function searchInbox(entries: InboxEntry[], query: string, limit: number): InboxEntry[] {
	if (limit <= 0 || entries.length === 0) return [];
	const tokens = (query ?? "")
		.toLowerCase()
		.split(/[^a-z0-9_]+/)
		.filter((t) => t.length >= 3);
	if (tokens.length === 0) {
		return entries.slice(-limit).reverse();
	}
	const scored = entries.map((e, idx) => {
		const hay = e.text.toLowerCase();
		let score = 0;
		for (const tok of tokens) {
			if (hay.includes(tok)) score += 1;
		}
		return { entry: e, score, idx };
	});
	const matched = scored.filter((s) => s.score > 0);
	if (matched.length === 0) {
		return entries.slice(-limit).reverse();
	}
	matched.sort((a, b) => b.score - a.score || b.idx - a.idx);
	return matched.slice(0, limit).map((s) => s.entry);
}

/** Current size of `memory/inbox/notes.md` in bytes (0 if missing). */
export async function inboxSizeBytes(): Promise<number> {
	const path = inboxNotesPath();
	if (!existsSync(path)) return 0;
	try {
		const st = await stat(path);
		return st.size;
	} catch {
		return 0;
	}
}

// ---------------------------------------------------------------------------
// readEventsSince

export type Watermark = Record<string /* sessionId */, string /* lastEventId */>;

export type ReadEventsSinceOptions = {
	/**
	 * If set, skip any session JSONL file whose mtime (last-modified) is at or
	 * before this epoch-ms timestamp. Mirrors Claude Code's listSessionsTouchedSince
	 * pattern — limits the scan to recently active sessions so the dream pipeline
	 * never reprocesses the full historical event log on every run.
	 *
	 * Typical value: the epoch-ms timestamp written to last-dream.json after the
	 * previous successful dream run. Sessions already fully watermarked that have
	 * not been touched since then contribute zero new events and can be skipped
	 * cheaply without even opening the file.
	 */
	sessionMtimeSince?: number;
};

export async function readEventsSince(watermarks: Watermark, opts: ReadEventsSinceOptions = {}): Promise<Event[]> {
	const dir = eventsDir();
	if (!existsSync(dir)) return [];
	const files = (await readdir(dir)).filter((f) => f.endsWith(".jsonl")).sort();
	const out: Event[] = [];
	for (const file of files) {
		// Session mtime filter: skip files not touched since last dream (fast path).
		if (opts.sessionMtimeSince !== undefined) {
			try {
				const s = await stat(join(dir, file));
				if (s.mtimeMs <= opts.sessionMtimeSince) continue;
			} catch {
				continue;
			}
		}
		const sessionId = file.slice(0, -".jsonl".length);
		const since = watermarks[sessionId];
		const text = await readFile(join(dir, file), "utf8");
		for (const raw of text.split("\n")) {
			if (!raw) continue;
			let evt: Event;
			try {
				evt = JSON.parse(raw) as Event;
			} catch {
				continue; // skip torn write
			}
			if (since && evt.event_id <= since) continue;
			out.push(evt);
		}
	}
	// ULIDs are lexicographically time-ordered; stable global ordering.
	out.sort((a, b) => (a.event_id < b.event_id ? -1 : a.event_id > b.event_id ? 1 : 0));
	return out;
}

// ---------------------------------------------------------------------------
// Watermark — atomic write via tmp + rename

export async function readWatermark(): Promise<Watermark> {
	const path = watermarkPath();
	if (!existsSync(path)) return {};
	try {
		return JSON.parse(await readFile(path, "utf8")) as Watermark;
	} catch {
		return {};
	}
}

export async function writeWatermark(wm: Watermark): Promise<void> {
	await mkdir(eventsRoot(), { recursive: true });
	const path = watermarkPath();
	const tmp = `${path}.tmp.${randomBytes(6).toString("hex")}`;
	await writeFile(tmp, JSON.stringify(wm, null, 2) + "\n");
	await rename(tmp, path);
}

/** Advance the watermark for a session iff the new id is strictly greater. */
export function advanceWatermark(wm: Watermark, sessionId: string, eventId: string): Watermark {
	const cur = wm[sessionId];
	if (cur && cur >= eventId) return wm; // idempotent / no-regress
	return { ...wm, [sessionId]: eventId };
}

// ---------------------------------------------------------------------------
// readMemoryTree — hard byte+file caps

export type ReadMemoryOptions = {
	maxBytes?: number; // total content cap, default 24kB (SessionStart budget)
	maxFiles?: number; // file cap, default 8
	/**
	 * If true, append `"inbox"` to the roots list and tag any inbox-rooted
	 * block header with `(inbox)` so the agent knows the content is raw,
	 * uncurated capture (D3). Default: false. Callers on the SessionStart /
	 * UserPromptSubmit injection paths pass true so notes captured *this
	 * session* surface immediately. Dream's canonical reads keep the
	 * default false to avoid feedback loops.
	 */
	includeInbox?: boolean;
};

const DEFAULT_MAX_BYTES = 24 * 1024;
const DEFAULT_MAX_FILES = 8;

/**
 * Read .md files under the given roots. `roots` are relative to memoryDir()
 * (or absolute, but must resolve under memoryDir() — we refuse path escape).
 *
 * Returns a single concatenated string with `### relpath\n\n<body>` blocks.
 * Stops at the first cap (files OR bytes).
 */
export async function readMemoryTree(
	roots: string[],
	opts: ReadMemoryOptions = {},
): Promise<{ content: string; files: string[]; truncated: boolean }> {
	const maxBytes = opts.maxBytes ?? DEFAULT_MAX_BYTES;
	const maxFiles = opts.maxFiles ?? DEFAULT_MAX_FILES;
	const base = memoryDir();
	const collected: string[] = [];
	const files: string[] = [];
	let bytes = 0;
	let truncated = false;

	const effectiveRoots = opts.includeInbox && !roots.includes(INBOX_DIR)
		? [...roots, INBOX_DIR]
		: roots;
	const candidates = await collectMdFiles(base, effectiveRoots);
	for (const abs of candidates) {
		if (files.length >= maxFiles) {
			truncated = true;
			break;
		}
		// Strip YAML frontmatter before injecting. source_event_ids (fresh ULIDs)
		// and last_dreamed_at change on every dream touch; injecting them busts the
		// cross-session prompt cache even when the prose is unchanged. The model
		// does not need the frontmatter — the path header + markdown body suffice.
		const body = stripLeadingFrontmatter(await readFile(abs, "utf8")).trim();
		const rel = relative(base, abs);
		const isInboxBlock = rel === INBOX_DIR || rel.startsWith(`${INBOX_DIR}/`) || rel.startsWith(`${INBOX_DIR}\\`);
		const tag = isInboxBlock ? " (inbox)" : "";
		const block = `### ${rel}${tag}\n\n${body}`;
		// Enforce byte cap including the upcoming block + the joining "\n\n".
		const sep = collected.length ? 2 : 0;
		if (bytes + sep + Buffer.byteLength(block, "utf8") > maxBytes) {
			truncated = true;
			break;
		}
		collected.push(block);
		files.push(rel);
		bytes += sep + Buffer.byteLength(block, "utf8");
	}

	return { content: collected.join("\n\n"), files, truncated };
}

/**
 * Return relative paths of ALL .md files under the given roots, lexicographically sorted.
 * No content is read — callers use this as a compact file index for deduplication checks.
 * Significantly cheaper than readMemoryTree since it performs no file I/O beyond directory listing.
 */
export async function listAllMemoryFiles(
	roots: string[] = ["profile", "project", "tools"],
): Promise<string[]> {
	const base = memoryDir();
	const abs = await collectMdFiles(base, roots);
	return abs.map((p) => relative(base, p));
}

async function collectMdFiles(base: string, roots: string[]): Promise<string[]> {
	const seen = new Set<string>();
	const out: string[] = [];
	for (const root of roots) {
		const abs = isAbsolute(root) ? resolve(root) : resolve(base, root);
		// Refuse path escape outside memoryDir() — security boundary.
		const relToBase = relative(base, abs);
		if (relToBase.startsWith("..") || isAbsolute(relToBase)) {
			console.error(`[dream-memory] refusing path outside memoryDir: ${root}`);
			continue;
		}
		if (!existsSync(abs)) continue;
		const st = await stat(abs);
		if (st.isFile()) {
			if (abs.endsWith(".md") && !seen.has(abs)) {
				seen.add(abs);
				out.push(abs);
			}
		} else if (st.isDirectory()) {
			await walkMd(abs, seen, out);
		}
	}
	// Stable order: lexicographic relative path.
	out.sort((a, b) => relative(base, a).localeCompare(relative(base, b)));
	return out;
}

async function walkMd(dir: string, seen: Set<string>, out: string[]): Promise<void> {
	for (const ent of await readdir(dir, { withFileTypes: true })) {
		const p = join(dir, ent.name);
		if (ent.isDirectory()) {
			await walkMd(p, seen, out);
		} else if (ent.isFile() && ent.name.endsWith(".md") && !seen.has(p)) {
			seen.add(p);
			out.push(p);
		}
	}
}

// ---------------------------------------------------------------------------
// searchMemory — recall search over qmd/search-vector backends,
// timeout-bounded.
//
// QMD result row shape (qmd 2.0.1, confirmed empirically):
//   { docid, score, file: "qmd://<collection>/<rel>.md", title,
//     snippet: "@@ -<start>,<count> @@\n<text>\n", context? }
// We map this into our SearchHit shape so callers (extension.ts,
// harness-cli.ts) keep their existing field names (`permalink`,
// `matched_chunk`, `content`).
//
// DREAM_BM_CMD is preserved as a deprecated alias for DREAM_QMD_CMD so
// existing test fixtures keep working through the v0→v1 transition. The
// fallback for `searchMemory` to bm-shaped JSON is intentional during the
// pivot: tests pass `{results:[...]}`, the wild path emits `[...]`. We
// detect both.

export type SearchHit = {
	title: string;
	permalink: string;
	score?: number;
	content?: string;
	matched_chunk?: string;
	file_path?: string;
	docid?: string;
};

export type SearchResult = {
	results: SearchHit[];
	timedOut: boolean;
	error?: string;
};

export type SearchOptions = {
	timeoutMs?: number; // default 1500ms
	/**
	 * Single collection to query. For multi-collection federation pass
	 * `collections` instead. If neither is set, falls back to
	 * `DREAM_QMD_COLLECTION` env var, then `DEFAULT_QMD_COLLECTION`.
	 */
	collection?: string;
	/**
	 * Multiple collections to query in one federated request. Used by
	 * active-recall to span pi-memory + scars + changes simultaneously.
	 * Takes precedence over `collection` when both are set.
	 */
	collections?: string[];
	qmdCmd?: string; // override binary for tests
	pageSize?: number; // default 5
	/**
	 * @deprecated v0 alias retained for tests / settings still using DREAM_BM_CMD.
	 * Prefer `qmdCmd` / `DREAM_QMD_CMD`. Removed in a future major.
	 */
	bmCmd?: string;
	/**
	 * @deprecated v0 alias for `collection`. Prefer `collection` /
	 * `DREAM_QMD_COLLECTION`.
	 */
	project?: string;
	/** Override the qmd-health probe budget. Defaults to 200ms. Tests bump this. */
	probeTimeoutMs?: number;
	/**
	 * QMD recall mode. `"search"` is BM25 only. `"query"` is the external
	 * hybrid HTTP path: qmd lex + vector sidecar + optional TEI rerank.
	 * Subprocess query is intentionally blocked because upstream qmd's
	 * in-process vector/rerank path is fragile on Apple Silicon.
	 */
	qmdMode?: "search" | "query";
	/**
	 * Pool size for hybrid rerank. Only applies when `qmdMode === "query"`.
	 * HTTP hybrid uses it as the default lex/vec pool. Default: 80.
	 */
	candidateLimit?: number;
	/**
	 * Override reranking for the HTTP daemon path. When false, disables cross-encoder
	 * reranking even in hybrid mode. Useful for collections not fully loaded in the daemon.
	 * Default: true (rerank enabled). Env: RECALL_RERANK=0 disables globally.
	 */
	rerank?: boolean;
	/**
	 * If set, use the qmd HTTP daemon at this port instead of spawning a
	 * subprocess. Much faster (no process cold-start): 50ms vs 1-6s.
	 * Override with DREAM_QMD_HTTP_PORT env var. Set to 0 only for BM25
	 * subprocess fallback (`qmdMode:"search"`).
	 */
	httpPort?: number;
	/**
	 * Two-pass retrieval: additional sub-queries issued in parallel after the
	 * main query. Results are merged by permalink (highest score wins) and the
	 * top `pageSize` returned. Used for multi-topic prompts where the combined
	 * query ranks individual relevant notes below the cutoff. HTTP path only.
	 */
	extraQueries?: string[];
};

const DEFAULT_SEARCH_TIMEOUT_MS = 1500;
const DEFAULT_QMD_COLLECTION = "dream-memory";

/** QMD's bare-array row shape — see qmd query --json. */
export type QmdQueryRow = {
	docid?: string;
	score?: number;
	file?: string; // qmd://<collection>/<rel>.md
	title?: string;
	snippet?: string;
	context?: string;
};

/** Strip `qmd://<collection>/` prefix; return relative path or the input. */
function qmdUriToRel(file: string | undefined): string | undefined {
	if (!file) return undefined;
	const m = /^qmd:\/\/[^/]+\/(.*)$/.exec(file);
	return m ? m[1] : file;
}

/** Strip the `@@ -N,M @@` header (and optional `(K before, L after)` tail). */
function snippetText(snippet: string | undefined): string {
	if (!snippet) return "";
	return snippet.replace(/^@@\s*-[^\n]*\n?/, "");
}

/** Map a QMD row → our SearchHit shape. */
export function qmdRowToHit(row: QmdQueryRow): SearchHit {
	const rel = qmdUriToRel(row.file) ?? "";
	const snippet = snippetText(row.snippet);
	const hit: SearchHit = {
		title: row.title ?? rel,
		permalink: rel.replace(/\.md$/, ""),
	};
	if (typeof row.score === "number") hit.score = row.score;
	if (snippet) hit.matched_chunk = snippet;
	if (snippet) hit.content = snippet;
	if (rel) hit.file_path = rel;
	if (row.docid) hit.docid = row.docid;
	return hit;
}

/**
 * Parse the stdout of `qmd query --json` (or a v0 bm-shaped fallback).
 * Returns [] on JSON failure rather than throwing — the dispatcher swallows
 * empty results and surfaces a search error string upstream.
 */
export function parseSearchStdout(stdout: string): SearchHit[] {
	const trimmed = stdout.trim();
	if (!trimmed) return [];
	try {
		const parsed = JSON.parse(trimmed);
		if (Array.isArray(parsed)) {
			return (parsed as QmdQueryRow[]).map(qmdRowToHit);
		}
		if (parsed && typeof parsed === "object" && Array.isArray((parsed as { results?: unknown[] }).results)) {
			// Legacy bm shape `{results: SearchHit[]}` — pass through unchanged.
			return (parsed as { results: SearchHit[] }).results;
		}
		return [];
	} catch {
		return [];
	}
}

/** Tracks per-(cmd,collection) keys whose QmdUnhealthy event we've already written. */
const loggedUnhealthy = new Set<string>();

async function recordQmdUnhealthyOnce(
