// ---------------------------------------------------------------------------
// HTTP daemon fast path — skips subprocess spawn entirely.
// The qmd HTTP daemon (/query endpoint) keeps SQLite + embeddings warm;
// response time is ~50ms vs 1-6s cold subprocess.
//
// Response `file` field is "<collection>/<rel>.md" (no qmd:// scheme).
// We strip the collection prefix to get the same permalink as the CLI path.

function httpFileToRel(file: string | undefined): string {
	if (!file) return "";
	// "dream-memory/project/foo.md" → "project/foo.md"
	const slash = file.indexOf("/");
	return slash >= 0 ? file.slice(slash + 1) : file;
}

function httpRowToHit(row: Record<string, unknown>): SearchHit {
	const rel = httpFileToRel(row.file as string | undefined);
	const permalink = rel.replace(/\.md$/, "");
	const snippet = (row.snippet as string | undefined) ?? "";
	const hit: SearchHit = {
		title: (row.title as string | undefined) ?? permalink,
		permalink,
	};
	if (typeof row.score === "number") hit.score = row.score;
	if (snippet) { hit.matched_chunk = snippet; hit.content = snippet; }
	if (rel) hit.file_path = rel;
	if (row.docid) hit.docid = row.docid as string;
	return hit;
}

/**
 * Default char cap for queries shipped to qmd /query and TEI /rerank.
 * Cross-encoder rerankers and bi-encoder embed models both have a 512-token
 * hard limit; 1024 chars (~256 tokens) leaves comfortable headroom. Override
 * via `DREAM_QUERY_MAX_CHARS` for experiments.
 */
export const DEFAULT_QUERY_MAX_CHARS = 1024;
const DEFAULT_RERANK_TIMEOUT_MS = 15_000;
const MIN_RERANK_TIMEOUT_MS = 250;
const MAX_RERANK_TIMEOUT_MS = 15_000;
const DEFAULT_RERANK_CANDIDATES = 60;
const MAX_RERANK_CANDIDATES = 100;
const DEFAULT_HYBRID_LEX_CANDIDATES = 80;
const DEFAULT_HYBRID_VEC_CANDIDATES = 80;
const DEFAULT_HYBRID_FUSED_CANDIDATES = 100;
const MAX_HYBRID_CANDIDATES = 200;

export function normaliseQmdQuery(query: string, maxChars?: number): string {
	const envCap = Number(process.env.DREAM_QUERY_MAX_CHARS ?? "");
	const cap = maxChars ?? (Number.isFinite(envCap) && envCap > 0 ? envCap : DEFAULT_QUERY_MAX_CHARS);
	const cleaned = query
		.replace(/-/g, " ")
		.replace(/["']/g, " ")
		.replace(/[{}[\]():,|`<>;\\]/g, " ")
		.replace(/[\u0000-\u001f\u007f]+/g, " ")
		.replace(/\s+/g, " ")
		.trim();
	return cleaned.length > cap ? cleaned.slice(0, cap) : cleaned;
}

function boundedInt(raw: string | undefined, fallback: number, min: number, max: number): number {
	if (raw === undefined) return fallback;
	const n = Number(raw);
	if (!Number.isFinite(n)) return fallback;
	return Math.min(max, Math.max(min, Math.floor(n)));
}

function remainingBudgetMs(deadlineMs: number): number {
	return Math.max(0, deadlineMs - Date.now());
}

async function fetchWithTimeout(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
	const ctrl = new AbortController();
	if (timeoutMs <= 0) ctrl.abort();
	const timer = timeoutMs > 0 ? setTimeout(() => ctrl.abort(), timeoutMs) : undefined;
	try {
		return await fetch(url, { ...init, signal: ctrl.signal });
	} finally {
		if (timer) clearTimeout(timer);
	}
}

function logRerankDiagnostic(label: string | undefined, reason: string): void {
	console.warn(`[dream-memory] TEI rerank ${label ?? "request"} failed: ${reason}`);
}

// ---------------------------------------------------------------------------
// External reranker (TEI / HuggingFace text-embeddings-inference).
//
// qmd's built-in `node-llama-cpp` reranker leaks Metal-backed IOSurface memory
// on Apple Silicon (see `~/.pi/agent/memory/profile/qmd-mcp-memory-leak.md`).
// When DREAM_RERANK_PROVIDER=tei is set, we POST {query, texts} to TEI's
// /rerank endpoint, then sort by TEI score and slice to pageSize. Active
// recall's hybrid HTTP path keeps qmd on lex-only candidates and gets vec
// candidates from qmd-vector-sidecar, so qmd's RSS-heavy vec branch is not on
// the hot path.
//
// TEI lives in its own process (Rust/Candle), so allocator pressure does not
// touch qmd's Node heap. See `docs/reranking-decision.md`.
// ---------------------------------------------------------------------------

/** Resolved rerank-provider config; null when external rerank is disabled. */
function resolveRerankProvider(): {
	url: string;
	timeoutMs: number;
	candidates: number;
} | null {
	const provider = process.env.DREAM_RERANK_PROVIDER;
	if (!provider || provider === "qmd" || provider === "none") return null;
	if (provider !== "tei") return null; // future: other providers
	const url = process.env.DREAM_RERANK_URL ?? "http://127.0.0.1:8182/rerank";
	const timeoutMs = boundedInt(
		process.env.DREAM_RERANK_TIMEOUT_MS,
		DEFAULT_RERANK_TIMEOUT_MS,
		MIN_RERANK_TIMEOUT_MS,
		MAX_RERANK_TIMEOUT_MS,
	);
	const candidates = boundedInt(
		process.env.DREAM_RERANK_CANDIDATES,
		DEFAULT_RERANK_CANDIDATES,
		1,
		MAX_RERANK_CANDIDATES,
	);
	return { url, timeoutMs, candidates };
}

/**
 * Re-score `texts` against `query` via a TEI-shaped /rerank endpoint.
 * Returns the indices sorted by descending relevance, with scores attached.
 * Empty array on any failure — caller falls back to the pre-rerank order.
 *
 * TEI response shape (text-embeddings-router v1.x):
 *   [{ index: number, score: number, text?: string }, ...] // already sorted desc
 */
export async function rerankViaTei(
	query: string,
	texts: string[],
	opts: { url: string; timeoutMs: number; label?: string },
): Promise<{ index: number; score: number }[]> {
	if (texts.length === 0) return [];
	if (opts.timeoutMs <= 0) {
		logRerankDiagnostic(opts.label, "search budget exhausted");
		return [];
	}
	try {
		const resp = await fetchWithTimeout(opts.url, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ query, texts, raw_scores: false }),
		}, opts.timeoutMs);
		if (!resp.ok) {
			logRerankDiagnostic(opts.label, `HTTP ${resp.status}`);
			return [];
		}
		const data = (await resp.json()) as Array<{ index: number; score: number }>;
		if (!Array.isArray(data)) {
			logRerankDiagnostic(opts.label, "invalid response shape");
			return [];
		}
		return data
			.filter((d) => typeof d.index === "number" && typeof d.score === "number")
			.sort((a, b) => b.score - a.score);
	} catch (err) {
		const e = err as Error;
		const reason = e.name === "AbortError" ? `timeout after ${opts.timeoutMs}ms` : e.message;
		logRerankDiagnostic(opts.label, reason);
		return [];
	}
}

// =====================================================================
// External vector path — DREAM_EMBED_MODE shadow A/B.
//
// `searchMemory` dispatches based on $DREAM_EMBED_MODE:
//
//   qmd (default)  serve qmd, no shadow                              (today)
//   shadow         serve qmd, sample-log shadow vs sidecar /search
//   shadow-tei     serve sidecar /search, sample-log shadow vs qmd
//   tei            serve sidecar /search only                        (cutover)
//
// The shadow arm runs in the background after the served result returns
// to the caller. It never affects served latency or correctness. Shadow
// errors are swallowed; shadow log writes are best-effort.
//
// See docs/mlx-port-decision-v2.md and docs/mlx-port-runbook.md.
// =====================================================================

export type EmbedMode = "qmd" | "tei" | "shadow" | "shadow-tei";

const DEFAULT_EMBED_MODE: EmbedMode = "qmd";
const DEFAULT_SHADOW_SAMPLE_RATE = 0.25;

function embedMode(): EmbedMode {
	const raw = process.env.DREAM_EMBED_MODE;
	if (raw === "tei" || raw === "shadow" || raw === "shadow-tei" || raw === "qmd") return raw;
	return DEFAULT_EMBED_MODE;
}

function shadowSampleRate(): number {
	const raw = Number(process.env.DREAM_SHADOW_SAMPLE_RATE);
	if (!Number.isFinite(raw) || raw < 0 || raw > 1) return DEFAULT_SHADOW_SAMPLE_RATE;
	return raw;
}

function shouldFireShadow(): boolean {
	const rate = shadowSampleRate();
	if (rate <= 0) return false;
	if (rate >= 1) return true;
	return Math.random() < rate;
}

function vectorSidecarUrl(): string {
	const raw = process.env.DREAM_VECTOR_URL ?? "http://127.0.0.1:8184";
	return raw.endsWith("/search") ? raw : `${raw.replace(/\/$/, "")}/search`;
}

function shadowLogPath(): string {
	return join(eventsRoot(), "ab-shadow.jsonl");
}

/** Map a sidecar /search hit row → our SearchHit shape. */
function sidecarRowToHit(row: {
	chunk_id?: string;
	source_doc_id?: string;
	path?: string;
	title?: string | null;
	content?: string;
	score?: number;
	distance?: number;
}): SearchHit {
	const path = row.path ?? row.source_doc_id ?? "";
	const hit: SearchHit = {
		title: row.title ?? path,
		permalink: path.replace(/\.md$/, ""),
	};
	if (typeof row.score === "number") hit.score = row.score;
	else if (typeof row.distance === "number") hit.score = Math.max(0, 1 - row.distance / 2);
	if (row.content) {
		hit.content = row.content;
		hit.matched_chunk = row.content;
	}
	if (path) hit.file_path = path;
	if (row.chunk_id) hit.docid = row.chunk_id;
	return hit;
}

function searchHitRerankText(hit: SearchHit): string {
	return hit.matched_chunk ?? hit.content ?? hit.title ?? "";
}

function normaliseSearchPath(path: string | undefined): string {
	return (path ?? "")
		.replace(/\.md$/, "")
		.replace(/^(dream-memory|memory)\//, "");
}

function searchHitKey(hit: SearchHit): string {
	return normaliseSearchPath(hit.permalink) ||
		normaliseSearchPath(hit.file_path) ||
		hit.title;
}

function mergeSearchHits(groups: SearchHit[][]): SearchHit[] {
	const best = new Map<string, SearchHit>();
	for (const group of groups) {
		for (const hit of group) {
			const key = searchHitKey(hit);
			const prev = best.get(key);
			if (!prev || (hit.score ?? 0) > (prev.score ?? 0)) best.set(key, hit);
		}
	}
	return [...best.values()];
}

function reciprocalRankFuse(groups: SearchHit[][], limit: number): SearchHit[] {
	const k = 60;
	const fused = new Map<string, { hit: SearchHit; score: number; bestRank: number }>();
	for (const group of groups) {
		group.forEach((hit, index) => {
			const key = searchHitKey(hit);
			const rank = index + 1;
			const score = 1 / (k + rank);
			const prev = fused.get(key);
			if (!prev) {
				fused.set(key, { hit, score, bestRank: rank });
				return;
			}
			prev.score += score;
			if ((hit.score ?? 0) > (prev.hit.score ?? 0)) prev.hit = hit;
			prev.bestRank = Math.min(prev.bestRank, rank);
		});
	}
	return [...fused.values()]
		.sort((a, b) => (b.score - a.score) || (a.bestRank - b.bestRank))
		.slice(0, limit)
		.map(({ hit, score }) => ({ ...hit, score }));
}

type RerankProviderConfig = NonNullable<ReturnType<typeof resolveRerankProvider>>;

async function rerankSearchHitsViaTei(
	query: string,
	hits: SearchHit[],
	pageSize: number,
	teiCfg: RerankProviderConfig,
	deadlineMs: number,
	label: string,
): Promise<SearchHit[] | null> {
	const candidates = hits.slice(0, teiCfg.candidates);
	const texts = candidates.map(searchHitRerankText);
	const rerankTimeoutMs = Math.min(teiCfg.timeoutMs, remainingBudgetMs(deadlineMs));
	// Silent skip when retrieval consumed the budget — TEI needs ≥ MIN_RERANK_TIMEOUT_MS
	// to be worth attempting. Caller falls through to the fused/vec order. No warn.
	if (rerankTimeoutMs < MIN_RERANK_TIMEOUT_MS) return null;
	const ranked = await rerankViaTei(normaliseQmdQuery(query), texts, {
		url: teiCfg.url,
		timeoutMs: rerankTimeoutMs,
		label,
	});
	if (ranked.length === 0) return null;
	const reordered: SearchHit[] = [];
	for (const r of ranked) {
		const hit = candidates[r.index];
		if (!hit) continue;
		reordered.push({ ...hit, score: r.score });
	}
	return reordered.slice(0, pageSize);
}

/**
 * Search via the qmd-vector-sidecar HTTP service. Pure vec retrieval; an
 * optional TEI rerank step reorders the top-K to keep the comparison vs
 * the qmd path fair (qmd also reranks via TEI).
 *
 * Errors return `{ results: [], timedOut, error }` — same shape as
 * `searchMemoryHttp`, so the served arm degrades gracefully.
 */
export async function searchVectorSidecar(
	query: string,
	opts: SearchOptions = {},
): Promise<SearchResult> {
	const url = vectorSidecarUrl();
	const pageSize = opts.pageSize ?? 5;
	const timeoutMs = opts.timeoutMs ?? DEFAULT_SEARCH_TIMEOUT_MS;
	const deadlineMs = Date.now() + timeoutMs;
	const rerank = opts.rerank !== false && process.env.RECALL_RERANK !== "0";
	const teiCfg = rerank ? resolveRerankProvider() : null;
	const k = teiCfg ? Math.max(pageSize, teiCfg.candidates) : pageSize;
	try {
		const resp = await fetchWithTimeout(url, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ query, k }),
		}, timeoutMs);
		if (!resp.ok) {
			return { results: [], timedOut: false, error: `sidecar: HTTP ${resp.status}` };
		}
		const data = (await resp.json()) as { hits?: Array<Parameters<typeof sidecarRowToHit>[0]> };
		const hits = data.hits ?? [];
		if (teiCfg && hits.length > 1) {
			const reranked = await rerankSearchHitsViaTei(
				query,
				hits.map(sidecarRowToHit),
				pageSize,
				teiCfg,
				deadlineMs,
				"sidecar",
			);
			if (reranked) {
				return { results: reranked, timedOut: false };
			}
			// TEI rerank failed — fall through to raw vec order.
		}
		return { results: hits.slice(0, pageSize).map(sidecarRowToHit), timedOut: false };
	} catch (err) {
		const isAbort = (err as Error).name === "AbortError";
		if (isAbort) return { results: [], timedOut: true };
		return { results: [], timedOut: false, error: `sidecar: ${(err as Error).message}` };
	}
}

/**
 * Human-readable key for the JSONL `top5_paths` field. Keeps the original
 * path/permalink shape so an operator scanning the log can tell which file
 * each arm returned.
 */
function top5Key(h: SearchHit): string {
	return h.permalink || h.file_path || h.title || "";
}

/**
 * Cross-arm canonical match key for overlap@5 / rank-correlation math.
 *
 * qmd produces collection-relative permalinks (`project/my-pi/boot-profile`).
 * The vector sidecar produces corpus-relative paths (`memory/project/my-pi/
 * boot-profile`). They never string-equal even when both arms return the same
 * file. Reducing to the file basename (no extension) gives a stable cross-arm
 * key. Trades collision risk (two files sharing a name in different dirs) for
 * cross-arm comparability. Acceptable for dream-memory/pi-memory corpora
 * where filenames are largely unique.
 */
function top5MatchKey(h: SearchHit): string {
	const raw = h.file_path || h.permalink || h.title || "";
	const base = raw.split("/").pop() ?? raw;
	return base.replace(/\.md$/, "");
}

function overlapAt5(a: SearchHit[], b: SearchHit[]): number {
	if (a.length === 0 && b.length === 0) return 1;
	if (a.length === 0 || b.length === 0) return 0;
	const sa = new Set(a.slice(0, 5).map(top5MatchKey));
	let hit = 0;
	for (const x of b.slice(0, 5)) if (sa.has(top5MatchKey(x))) hit++;
	return hit / 5;
}

function rankCorrelation(served: SearchHit[], shadow: SearchHit[]): number | null {
	// Spearman over the intersection of canonical basenames. Returns null when
	// the intersection is too small for a meaningful rank.
	const aRank = new Map<string, number>();
	served.forEach((h, i) => aRank.set(top5MatchKey(h), i));
	const pairs: Array<[number, number]> = [];
	shadow.forEach((h, i) => {
		const r = aRank.get(top5MatchKey(h));
		if (r !== undefined) pairs.push([r, i]);
	});
	if (pairs.length < 3) return null;
	const n = pairs.length;
	let dSum = 0;
	for (const [a, b] of pairs) dSum += (a - b) ** 2;
	return 1 - (6 * dSum) / (n * (n * n - 1));
}

function shortQueryHash(query: string): string {
	return createHash("sha256").update(query).digest("hex").slice(0, 12);
}

async function logShadowSample(payload: {
	mode: "shadow" | "shadow-tei";
	query: string;
	served: { arm: "qmd" | "tei"; latencyMs: number; results: SearchHit[] };
	shadow: { arm: "qmd" | "tei"; latencyMs: number; results: SearchHit[] };
}): Promise<void> {
	const rec = {
		ts: Date.now(),
		mode: payload.mode,
		query_hash: shortQueryHash(payload.query),
		served: {
			arm: payload.served.arm,
			latency_ms: payload.served.latencyMs,
			top5_paths: payload.served.results.slice(0, 5).map(top5Key),
		},
		shadow: {
			arm: payload.shadow.arm,
			latency_ms: payload.shadow.latencyMs,
			top5_paths: payload.shadow.results.slice(0, 5).map(top5Key),
		},
		overlap_at_5: overlapAt5(payload.served.results, payload.shadow.results),
		rank_corr: rankCorrelation(payload.served.results, payload.shadow.results),
	};
	try {
		const path = shadowLogPath();
		await mkdir(dirname(path), { recursive: true });
		await appendFile(path, `${JSON.stringify(rec)}\n`);
	} catch {
		// Best-effort log. Never throws.
	}
}

