96	// ---------------------------------------------------------------------------
97	// CLI flag parsing — minimal, no extra deps.
98	
99	export type Client = "pi" | "claude" | "codex";
100	
101	function parseArgs(argv: string[]): { client: Client; positional: string[] } {
102		let client: Client = "claude";
103		const positional: string[] = [];
104		for (let i = 0; i < argv.length; i++) {
105			const a = argv[i]!;
106			if (a === "--client") {
107				const next = argv[++i];
108				if (next !== "pi" && next !== "claude" && next !== "codex") {
109					throw new Error(`--client must be one of pi|claude|codex, got: ${String(next)}`);
110				}
111				client = next;
112			} else if (a.startsWith("--client=")) {
113				const val = a.slice("--client=".length);
114				if (val !== "pi" && val !== "claude" && val !== "codex") {
115					throw new Error(`--client must be one of pi|claude|codex, got: ${val}`);
116				}
117				client = val;
118			} else {
119				positional.push(a);
120			}
121		}
122		return { client, positional };
123	}
