125	// ---------------------------------------------------------------------------
126	// Normalisation across {pi, claude, codex} hook payloads.
127	
128	export type NormalisedHook = {
129		client: Client;
130		sessionId: string;
131		cwd: string;
132		eventType: EventType;
133		payload: Record<string, unknown>;
134	};
135	
136	const CANONICAL_EVENTS: ReadonlySet<EventType> = new Set([
137		"SessionStart",
138		"UserPromptSubmit",
139		"PreToolUse",
140		"PostToolUse",
141		"Stop",
142	]);
143	
144	function pascal(s: string): string {
145		return s
146			.split(/[_\-\s]+/)
147			.filter(Boolean)
148			.map((p) => p[0]!.toUpperCase() + p.slice(1))
149			.join("");
150	}
151	
152	function pickEventType(input: Record<string, unknown>): EventType {
153		const candidates = [
154			input.hook_event_name,
155			input.hookEventName,
156			input.event_type,
157			input.eventType,
158			input.event,
159		];
160		for (const c of candidates) {
161			if (typeof c === "string" && c.length > 0) {
162				const p = pascal(c);
163				if (CANONICAL_EVENTS.has(p)) return p;
164				return p; // pass through unknown but well-formed names (logged via appendEvent)
165			}
166		}
167		throw new Error("hook payload missing event type (hook_event_name / event_type)");
168	}
169	
170	function pickFirstString(input: Record<string, unknown>, keys: string[], dflt: string): string {
171		for (const k of keys) {
172			const v = input[k];
173			if (typeof v === "string" && v.length > 0) return v;
174		}
175		return dflt;
176	}
177	
178	export function normalise(client: Client, raw: unknown): NormalisedHook {
179		if (!raw || typeof raw !== "object") {
180			throw new Error("hook payload must be a JSON object");
181		}
182		const input = raw as Record<string, unknown>;
183		const eventType = pickEventType(input);
184		const sessionId = pickFirstString(input, ["session_id", "sessionId"], "unknown-session");
185		const cwd = pickFirstString(input, ["cwd", "workspace_dir", "workspaceDir"], process.cwd());
186	
187		// Strip meta fields from the payload echo (keep them in event header).
188		const META = new Set([
189			"hook_event_name",
190			"hookEventName",
191			"event_type",
192			"eventType",
193			"event",
194			"session_id",
195			"sessionId",
196			"cwd",
197			"workspace_dir",
198			"workspaceDir",
199			"transcript_path",
200			"transcriptPath",
201		]);
202		const payload: Record<string, unknown> = {};
203		for (const [k, v] of Object.entries(input)) {
204			if (!META.has(k)) payload[k] = v;
205		}
206		return { client, sessionId, cwd, eventType, payload };
207	}
