209	// ---------------------------------------------------------------------------
210	// Time-bounded helpers.
211	
212	export class TimeoutError extends Error {
213		constructor(public readonly ms: number, public readonly where: string) {
214			super(`${where} exceeded ${ms}ms`);
215			this.name = "TimeoutError";
216		}
217	}
218	
219	export function withTimeout<T>(promise: Promise<T>, ms: number, where: string): Promise<T> {
220		return new Promise<T>((resolveP, rejectP) => {
221			const timer = setTimeout(() => rejectP(new TimeoutError(ms, where)), ms);
222			promise.then(
223				(v) => {
224					clearTimeout(timer);
225					resolveP(v);
226				},
227				(err) => {
228					clearTimeout(timer);
229					rejectP(err);
230				},
231			);
232		});
233	}
