235	// ---------------------------------------------------------------------------
236	// Stdin reader — bounded; refuses huge payloads.
237	
238	const MAX_STDIN_BYTES = 1024 * 1024; // 1MB
239	
240	async function readStdin(): Promise<string> {
241		if (process.stdin.isTTY) return "";
242		const chunks: Buffer[] = [];
243		let total = 0;
244		for await (const chunk of process.stdin) {
245			const buf = typeof chunk === "string" ? Buffer.from(chunk) : (chunk as Buffer);
246			total += buf.length;
247			if (total > MAX_STDIN_BYTES) {
248				throw new Error(`stdin payload exceeded ${MAX_STDIN_BYTES} bytes`);
249			}
250			chunks.push(buf);
251		}
252		return Buffer.concat(chunks).toString("utf8");
253	}
