255	// ---------------------------------------------------------------------------
256	// Cadence — Stop-handler dream enqueue.
257	
258	export async function eventsSinceFor(
259		sessionId: string,
260		sinceEventId?: string,
261		opts: { excludeEventTypes?: Set<string> } = {},
262	): Promise<number> {
263		const file = join(eventsDir(), `${sessionId}.jsonl`);
264		if (!existsSync(file)) return 0;
265		const text = await readFile(file, "utf8");
266		let n = 0;
267		for (const line of text.split("\n")) {
268			if (!line) continue;
269			try {
270				const e = JSON.parse(line) as { event_id?: string; event_type?: string };
271				if (opts.excludeEventTypes && e.event_type && opts.excludeEventTypes.has(e.event_type)) continue;
272				if (sinceEventId) {
273					if (e.event_id && e.event_id > sinceEventId) n += 1;
274				} else {
275					n += 1;
276				}
277			} catch {
278				// torn write
279			}
280		}
281		return n;
282	}
