284	async function maybeEnqueueDream(sessionId: string): Promise<boolean> {
285		// Write dream-pending whenever >=1 meaningful new event exists since the
286		// watermark for this session. "Stop" events are excluded — they are session
287		// housekeeping, not durable work. Time/session gates live in runner.ts.
288		const { readWatermark } = await import("./store.ts");
289		const wm = await readWatermark();
290		const sinceEventId = wm[sessionId];
291		const count = await eventsSinceFor(sessionId, sinceEventId, { excludeEventTypes: new Set(["Stop"]) });
292		const inboxBytes = await inboxSizeBytes();
293		const eventsTrigger = count >= 1;
294		const inboxTrigger = inboxBytes >= DREAM_INBOX_BYTES_THRESHOLD;
295		if (!eventsTrigger && !inboxTrigger) return false;
296		const marker = join(eventsRoot(), "dream-pending");
297		await mkdir(eventsRoot(), { recursive: true });
298		await writeFile(
299			marker,
300			JSON.stringify({
301				at: new Date().toISOString(),
302				sessionId,
303				count,
304				inbox_bytes: inboxBytes,
305				reason: eventsTrigger
306					? (inboxTrigger ? "events+inbox" : "events")
307					: "inbox",
308			}) + "\n",
309		);
310		return true;
311	}
