333	export async function dispatchSessionStart(hook: NormalisedHook): Promise<DispatchResult> {
334		const slug = await resolveProjectSlug(hook.cwd);
335		const started = Date.now();
336		// CACHE CRITICAL: this dispatcher returns only the per-cwd persistent
337		// memory — project/<slug>/MEMORY.md. The stable, global profile/** snapshot
338		// is injected separately via the extension's systemPrompt:build filter so it
339		// joins the cross-cwd cacheable base instead of the per-cwd tail. Never
340		// inject inbox/raw capture here: it carries event ids and timestamps that
341		// change between sessions.
342		//
343		// DETERMINISM (no timeout): loadProjectContext is a single local readFile
344		// (readIndexFile → MEMORY.md) — no subprocess, no network, sub-millisecond.
345		// The old wall-clock race made the first-turn bytes nondeterministic (a fast
346		// session got the full file, a cold one timed out to ""), bursting the
347		// cross-session prompt cache for this cwd. Claude Code loads CLAUDE.md the
348		// same way — a plain file read. Regression: test/session-start.test.ts.
349		const { content, files } = await loadProjectContext(slug, {
350			maxBytes: SESSION_START_MAX_BYTES,
351			maxFiles: SESSION_START_MAX_FILES,
352		});
353		const bytes = Buffer.byteLength(content, "utf8");
354		void appendEvent({
355			sessionId: hook.sessionId,
356			client: hook.client,
357			cwd: hook.cwd,
358			projectSlug: slug,
359			eventType: "RecallInjected",
360			payload: {
361				where: "SessionStart",
362				bytes,
363				latency_ms: Date.now() - started,
364				files: files.length,
365				qmd: { state: "skipped", hits: 0, permalinks: [] },
366			},
367		});
368		void getHCTel().then(({ withSpan }) => withSpan("dispatch.sessionStart", {
369			bytes_returned: bytes,
370			files_returned: files.length,
371		}, async () => {}));
372		return { stdout: content, timedOut: false };
373	}
