375	export async function dispatchUserPromptSubmit(hook: NormalisedHook): Promise<DispatchResult> {
376		const slug = await resolveProjectSlug(hook.cwd);
377		const query = typeof hook.payload.prompt === "string" ? hook.payload.prompt : "";
378	
379		// P3-ISSUE-1 fix: persist the prompt itself before doing recall, so the
380		// dream consolidation phase can see what the user actually asked. Previous
381		// behaviour appended only MemoryInjectionTimeout / nothing, which made
382		// `dream events tail` blind to user intent inside Pi sessions.
383		// Fire-and-forget — we never want event-log latency to block the agent
384		// loop, and the redaction layer + payload_hash live in appendEvent itself.
385		void appendEvent({
386			sessionId: hook.sessionId,
387			client: hook.client,
388			cwd: hook.cwd,
389			projectSlug: slug,
390			eventType: "UserPromptSubmit",
391			payload: { prompt: query, ...(hook.payload.first_turn ? { first_turn: true } : {}) },
392		});
393	
394		if (!query.trim()) return { stdout: "", timedOut: false };
395		try {
396			const started = Date.now();
397			// Two recall sources in parallel under the SAME budget:
398			//   - qmd (canonical wiki, vector + BM25)
399			//   - inbox (raw same-session capture; no qmd dependency — fixes
400			//     the latency cliff that motivated this whole change)
401			// Either, both, or none may produce hits. We never let one tool's
402			// failure or absence suppress the other.
403			const [qmd, inboxEntries] = await withTimeout(
404				Promise.all([
405					searchMemory(query, userPromptQmdSearchOptions()),
406					readInbox().then((all) => searchInbox(all, query, USER_PROMPT_INBOX_TOP_N))
407						.catch(() => [] as InboxEntry[]),
408				]),
409				USER_PROMPT_SEARCH_MS + 50,
410				"UserPromptSubmit search",
411			);
412			const latency_ms = Date.now() - started;
413			const anyTimedOut = qmd.timedOut;
414			const qmdShortCircuit = isQmdUnhealthyError(qmd.error);
415			if (anyTimedOut && !qmdShortCircuit) {
416				void appendEvent({
417					sessionId: hook.sessionId,
418					client: hook.client,
419					cwd: hook.cwd,
420					projectSlug: slug,
421					eventType: "MemoryInjectionTimeout",
422					payload: {
423						where: "UserPromptSubmit",
424						budget_ms: USER_PROMPT_SEARCH_MS,
425						qmd_timed_out: qmd.timedOut,
426					},
427				});
428			}
429			// Render inbox first (raw, freshest) then ranked merged hits below.
430			const inboxBlock = renderInboxBlock(inboxEntries, USER_PROMPT_INBOX_MAX_BYTES);
431			const inboxBytes = Buffer.byteLength(inboxBlock, "utf8");
432			const remainingBytes = Math.max(0, USER_PROMPT_MAX_BYTES - inboxBytes - (inboxBlock ? 2 : 0));
433			const rankedStdout = mergeRecallBlocks(
434				[{ heading: "qmd notes", hits: qmd.results.slice(0, USER_PROMPT_TOP_N) }],
435				remainingBytes,
436			);
437			const stdout = [inboxBlock, rankedStdout].filter(Boolean).join("\n\n");
438			const recall = stdout
439				? {
440						bytes: Buffer.byteLength(stdout, "utf8"),
441						latency_ms,
442						qmd: {
443							state: qmd.timedOut ? "timeout" as const : qmdShortCircuit ? "unhealthy" as const : qmd.error ? "error" as const : "ok" as const,
444							hits: qmd.results.length,
445							permalinks: qmd.results.slice(0, USER_PROMPT_TOP_N).map((h) => h.permalink),
446						},
447						inbox_hits: inboxEntries.length,
448						inbox_preview: inboxEntries.slice(0, USER_PROMPT_INBOX_TOP_N).map((e) => previewText(e.text)),
449					}
450				: undefined;
451			// Fire-and-forget RecallInjected — records what was actually injected
452			// so `dream recall watch` and `dream recall last` have real data.
453			if (stdout && recall) {
454				void appendEvent({
455					sessionId: hook.sessionId,
456					client: hook.client,
457					cwd: hook.cwd,
458					projectSlug: slug,
459					eventType: "RecallInjected",
460					payload: {
461						where: "UserPromptSubmit",
462						...recall,
463					},
464				});
465			}
466	
467			// Telemetry: counters always recorded (D5), span at 10% head-sampling.
468			void getHCTel().then(({ recordCounter, recordHistogram, withSpan }) => {
469				recordCounter("dream_memory.recall.hits", qmd.results.length, { source: "qmd" });
470				recordCounter("dream_memory.recall.hits", inboxEntries.length, { source: "inbox" });
471				recordHistogram("dream_memory.recall.latency_ms", latency_ms, { source: "qmd" });
472				if (Math.random() < 0.1) {
473					void withSpan("dispatch.userPromptSubmit", {
474						prompt_chars: query.length,
475						inbox_hits: inboxEntries.length,
476						qmd_hits: qmd.results.length,
477					}, async () => {});
478				}
479			});
480	
481			return { stdout, timedOut: anyTimedOut, ...(recall ? { recall } : {}) };
482		} catch (err) {
483			if (err instanceof TimeoutError) {
484				void appendEvent({
485					sessionId: hook.sessionId,
486					client: hook.client,
487					cwd: hook.cwd,
488					projectSlug: slug,
489					eventType: "MemoryInjectionTimeout",
490					payload: { where: "UserPromptSubmit", budget_ms: USER_PROMPT_SEARCH_MS },
491				});
492				return { stdout: "", timedOut: true };
493			}
494			throw err;
495		}
496	}
