498	/** Collapse whitespace and truncate to a short single-line preview for UI notifications. */
499	export function previewText(text: string, max = 32): string {
500		const flat = text.replace(/\s+/g, " ").trim();
501		return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat;
502	}
