504	/**
505	 * Render up to maxBytes of inbox entries as a `## inbox (inbox)` block.
506	 * Newest-first within the input order. Returns "" if no entries fit.
507	 */
508	export function renderInboxBlock(entries: InboxEntry[], maxBytes: number): string {
509		if (entries.length === 0 || maxBytes <= 0) return "";
510		const header = `## inbox (inbox)`;
511		let bytes = Buffer.byteLength(header, "utf8");
512		const parts: string[] = [header];
513		for (const e of entries) {
514			const block = `### ${e.event_id}  · ${e.ts}\n\n${e.text}`;
515			const sep = 2;
516			const sz = Buffer.byteLength(block, "utf8");
517			if (bytes + sep + sz > maxBytes) break;
518			parts.push(block);
519			bytes += sep + sz;
520		}
521		return parts.length > 1 ? parts.join("\n\n") : "";
522	}
523	
524	/**
525	 * Merge ranked hit lists into one `<recalled-memory>`-ready string.
526	 * Round-robin so no source can starve the others if several produce hits;
527	 * each hit gets a `## <heading>` group header the first time it appears.
528	 * Stops as soon as the next block would exceed `maxBytes`.
529	 */
530	export function mergeRecallBlocks(
531		blocks: Array<{ heading: string; hits: SearchHit[] }>,
532		maxBytes: number,
533	): string {
534		const sources = blocks.map((b) => ({ heading: b.heading, hits: b.hits, idx: 0, emitted: false }));
535		const out: string[] = [];
536		let bytes = 0;
537		let remaining = sources.reduce((n, s) => n + s.hits.length, 0);
538		while (remaining > 0) {
539			let progressed = false;
540			for (const s of sources) {
541				if (s.idx >= s.hits.length) continue;
542				const hit = s.hits[s.idx]!;
543				const body = hit.matched_chunk ?? hit.content ?? "";
544				const pieces: string[] = [];
545				if (!s.emitted) pieces.push(`## ${s.heading}`);
546				pieces.push(`### ${hit.permalink}\n\n${body}`);
547				const block = pieces.join("\n\n");
548				const sep = out.length ? 2 : 0;
549				const sz = Buffer.byteLength(block, "utf8");
550				if (bytes + sep + sz > maxBytes) {
551					remaining = 0;
552					break;
553				}
554				out.push(block);
555				bytes += sep + sz;
556				s.idx++;
557				s.emitted = true;
558				remaining--;
559				progressed = true;
560			}
561			if (!progressed) break;
562		}
563		return out.join("\n\n");
564	}
