593	// ---------------------------------------------------------------------------
594	// Top-level dispatcher with the 200ms wall budget.
595	
596	export async function dispatch(hook: NormalisedHook): Promise<DispatchResult> {
597		const handler = (() => {
598			switch (hook.eventType) {
599				case "SessionStart":
600					return dispatchSessionStart(hook);
601				case "UserPromptSubmit":
602					return dispatchUserPromptSubmit(hook);
603				case "PreToolUse":
604				case "PostToolUse":
605					return dispatchToolEvent(hook);
606				case "Stop":
607					return dispatchStop(hook);
608				default:
609					return dispatchToolEvent(hook); // unknown → just log
610			}
611		})();
612		try {
613			return await withTimeout(handler, TOTAL_WALL_BUDGET_MS, `${hook.eventType} total`);
614		} catch (err) {
615			if (err instanceof TimeoutError) {
616				// Best-effort breadcrumb. Don't await — we're already over budget.
617				void (async () => {
618					try {
619						const slug = await resolveProjectSlug(hook.cwd);
620						await appendEvent({
621							sessionId: hook.sessionId,
622							client: hook.client,
623							cwd: hook.cwd,
624							projectSlug: slug,
625							eventType: "MemoryInjectionTimeout",
626							payload: { where: hook.eventType, budget_ms: TOTAL_WALL_BUDGET_MS },
627						});
628					} catch {
629						// swallow — we already missed the budget
630					}
631				})();
632				return { stdout: "", timedOut: true };
633			}
634			throw err;
635		}
636	}
