641	export async function main(argv = process.argv.slice(2)): Promise<number> {
642		let parsed: ReturnType<typeof parseArgs>;
643		try {
644			parsed = parseArgs(argv);
645		} catch (err) {
646			console.error(`[harness-cli] ${(err as Error).message}`);
647			return 2;
648		}
649		let raw: unknown;
650		try {
651			const text = await readStdin();
652			if (!text.trim()) {
653				console.error("[harness-cli] empty stdin; expected hook JSON payload");
654				return 2;
655			}
656			raw = JSON.parse(text);
657		} catch (err) {
658			console.error(`[harness-cli] bad stdin JSON: ${(err as Error).message}`);
659			return 2;
660		}
661		let hook: NormalisedHook;
662		try {
663			hook = normalise(parsed.client, raw);
664		} catch (err) {
665			console.error(`[harness-cli] normalise failed: ${(err as Error).message}`);
666			return 2;
667		}
668		try {
669			const r = await dispatch(hook);
670			if (r.stdout) process.stdout.write(r.stdout);
671			return 0;
672		} catch (err) {
673			// Programmer error past every guard. Log + non-zero.
674			console.error(`[harness-cli] dispatch crashed: ${(err as Error).stack ?? String(err)}`);
675			return 1;
676		}
677	}
678	
679	const isEntry = (() => {
680		try {
681			const url = new URL(import.meta.url);
682			return url.pathname === process.argv[1] || url.pathname.endsWith(process.argv[1] ?? "");
683		} catch {
684			return false;
685		}
686	})();
687	if (isEntry) {
688		main()
689			.then((code) => process.exit(code))
690			.catch((err) => {
691				console.error(err);
692				process.exit(1);
693			});
694	}
695	
696	// Suppress unused-import lint when imports above are referenced only by types.
697	void readdir;
