#!/usr/bin/env node
/**
 * harness-cli — single TS entrypoint for Claude Code / Codex shell wrappers
 * and the manual `pi` test path. The Pi extension calls store.ts in-process
 * (deliverable 5) and skips this CLI.
 *
 * Reads stdin JSON, normalises per-harness payloads into one shape, and
 * dispatches the right side-effect:
 *
 *   SessionStart     -> stdout = profile + project markdown (≤24kB / ≤8 files)
 *                       Promise.race(150ms); on timeout: appendEvent
 *                       MemoryInjectionTimeout, no stdout, exit 0.
 *   UserPromptSubmit -> stdout = top-5 search hits via `bm tool search-notes
 *                       --hybrid` (≤10kB), timeout-bounded; on timeout:
 *                       MemoryInjectionTimeout, no stdout, exit 0.
 *   PreToolUse       -> appendEvent only.
 *   PostToolUse      -> appendEvent only.
 *   Stop             -> appendEvent + write dream-pending marker if cadence
 *                       threshold met. Never invokes the dream itself.
 *
 * Hard rule: ≤200ms wall budget end-to-end. Hooks must NEVER block the
 * harness. Exit 0 on success, 0 on timeout-skip (logged event), non-zero
 * only on programmer error (bad CLI flags, malformed stdin JSON).
 */

import { readFile, writeFile, readdir, mkdir, stat } from "node:fs/promises";
import { existsSync } from "node:fs";
import { join } from "node:path";

import {
	appendEvent,
	eventsDir,
	eventsRoot,
	inboxSizeBytes,
	INBOX_MAX_BYTES,
	loadProjectContext,
	readInbox,
	resolveProjectSlug,
	searchInbox,
	searchMemory,
	type EventType,
	type InboxEntry,
	type SearchHit,
} from "./store.ts";
import { isQmdUnhealthyError } from "./qmd-health.ts";
// Lazy-load telemetry to avoid pulling opik → ai-sdk → js-tiktoken at boot.
let _hcTelModule: Promise<typeof import("./telemetry.ts")> | null = null;
function getHCTel() {
	if (!_hcTelModule) _hcTelModule = import("./telemetry.ts");
	return _hcTelModule;
}

// ---------------------------------------------------------------------------
// Budgets (locked by GOAL CONSTRAINTS).

export const SESSION_START_INJECTION_MS = 150;
export const SESSION_START_MAX_BYTES = 24 * 1024;
export const SESSION_START_MAX_FILES = 8;
/** Max inbox entries surfaced per UserPromptSubmit turn. */
export const USER_PROMPT_INBOX_TOP_N = 3;
/** Max bytes of inbox content injected per UserPromptSubmit turn. */
export const USER_PROMPT_INBOX_MAX_BYTES = 4 * 1024;

export const USER_PROMPT_SEARCH_MS = 8000; // upper search budget (qmd query + LLM expansion can take 1-6s)
export const USER_PROMPT_MAX_BYTES = 10 * 1024;
export const USER_PROMPT_TOP_N = 5;

export const TOTAL_WALL_BUDGET_MS = 200;

// Dream cadence (locked):
//   min(events_since_watermark >= 50, inbox_size >= 64kB, 4h elapsed, manual)
//   force after 24h with non-zero events.
// The inbox-size trigger (D7) makes the inbox self-draining: heavy
// note-taking forces consolidation before the spill threshold so notes.md
// stays small + responsive.
export const DREAM_EVENTS_THRESHOLD = 50;
export const DREAM_INBOX_BYTES_THRESHOLD = INBOX_MAX_BYTES;

function userPromptQmdSearchOptions(): Parameters<typeof searchMemory>[1] {
	const qmdMode = process.env.RECALL_QMD_MODE === "search" ? "search" : "query";
	const httpPort = process.env.DREAM_QMD_HTTP_PORT
		? Number(process.env.DREAM_QMD_HTTP_PORT)
		: 8181;
	const candidateLimit = process.env.RECALL_CANDIDATE_LIMIT
		? Number(process.env.RECALL_CANDIDATE_LIMIT)
		: 80;
	return {
		pageSize: USER_PROMPT_TOP_N,
		timeoutMs: USER_PROMPT_SEARCH_MS,
		qmdMode,
		candidateLimit,
		...(httpPort > 0 ? { httpPort } : {}),
	};
}

// ---------------------------------------------------------------------------
// CLI flag parsing — minimal, no extra deps.

export type Client = "pi" | "claude" | "codex";

function parseArgs(argv: string[]): { client: Client; positional: string[] } {
	let client: Client = "claude";
	const positional: string[] = [];
	for (let i = 0; i < argv.length; i++) {
		const a = argv[i]!;
		if (a === "--client") {
			const next = argv[++i];
			if (next !== "pi" && next !== "claude" && next !== "codex") {
				throw new Error(`--client must be one of pi|claude|codex, got: ${String(next)}`);
			}
			client = next;
		} else if (a.startsWith("--client=")) {
			const val = a.slice("--client=".length);
			if (val !== "pi" && val !== "claude" && val !== "codex") {
				throw new Error(`--client must be one of pi|claude|codex, got: ${val}`);
			}
			client = val;
		} else {
			positional.push(a);
		}
	}
	return { client, positional };
}

// ---------------------------------------------------------------------------
// Normalisation across {pi, claude, codex} hook payloads.

export type NormalisedHook = {
	client: Client;
	sessionId: string;
	cwd: string;
	eventType: EventType;
	payload: Record<string, unknown>;
};

const CANONICAL_EVENTS: ReadonlySet<EventType> = new Set([
	"SessionStart",
	"UserPromptSubmit",
	"PreToolUse",
	"PostToolUse",
	"Stop",
]);

function pascal(s: string): string {
	return s
		.split(/[_\-\s]+/)
		.filter(Boolean)
		.map((p) => p[0]!.toUpperCase() + p.slice(1))
		.join("");
}

function pickEventType(input: Record<string, unknown>): EventType {
	const candidates = [
		input.hook_event_name,
		input.hookEventName,
		input.event_type,
		input.eventType,
		input.event,
	];
	for (const c of candidates) {
		if (typeof c === "string" && c.length > 0) {
			const p = pascal(c);
			if (CANONICAL_EVENTS.has(p)) return p;
			return p; // pass through unknown but well-formed names (logged via appendEvent)
		}
	}
	throw new Error("hook payload missing event type (hook_event_name / event_type)");
}

function pickFirstString(input: Record<string, unknown>, keys: string[], dflt: string): string {
	for (const k of keys) {
		const v = input[k];
		if (typeof v === "string" && v.length > 0) return v;
	}
	return dflt;
}

export function normalise(client: Client, raw: unknown): NormalisedHook {
	if (!raw || typeof raw !== "object") {
		throw new Error("hook payload must be a JSON object");
	}
	const input = raw as Record<string, unknown>;
	const eventType = pickEventType(input);
	const sessionId = pickFirstString(input, ["session_id", "sessionId"], "unknown-session");
	const cwd = pickFirstString(input, ["cwd", "workspace_dir", "workspaceDir"], process.cwd());

	// Strip meta fields from the payload echo (keep them in event header).
	const META = new Set([
		"hook_event_name",
		"hookEventName",
		"event_type",
		"eventType",
		"event",
		"session_id",
		"sessionId",
		"cwd",
		"workspace_dir",
		"workspaceDir",
		"transcript_path",
		"transcriptPath",
	]);
	const payload: Record<string, unknown> = {};
	for (const [k, v] of Object.entries(input)) {
		if (!META.has(k)) payload[k] = v;
	}
	return { client, sessionId, cwd, eventType, payload };
}

// ---------------------------------------------------------------------------
// Time-bounded helpers.

export class TimeoutError extends Error {
	constructor(public readonly ms: number, public readonly where: string) {
		super(`${where} exceeded ${ms}ms`);
		this.name = "TimeoutError";
	}
}

export function withTimeout<T>(promise: Promise<T>, ms: number, where: string): Promise<T> {
	return new Promise<T>((resolveP, rejectP) => {
		const timer = setTimeout(() => rejectP(new TimeoutError(ms, where)), ms);
		promise.then(
			(v) => {
				clearTimeout(timer);
				resolveP(v);
			},
			(err) => {
				clearTimeout(timer);
				rejectP(err);
			},
		);
	});
}

// ---------------------------------------------------------------------------
// Stdin reader — bounded; refuses huge payloads.

const MAX_STDIN_BYTES = 1024 * 1024; // 1MB

async function readStdin(): Promise<string> {
	if (process.stdin.isTTY) return "";
	const chunks: Buffer[] = [];
	let total = 0;
	for await (const chunk of process.stdin) {
		const buf = typeof chunk === "string" ? Buffer.from(chunk) : (chunk as Buffer);
		total += buf.length;
		if (total > MAX_STDIN_BYTES) {
			throw new Error(`stdin payload exceeded ${MAX_STDIN_BYTES} bytes`);
		}
		chunks.push(buf);
	}
	return Buffer.concat(chunks).toString("utf8");
}

// ---------------------------------------------------------------------------
// Cadence — Stop-handler dream enqueue.

export async function eventsSinceFor(
	sessionId: string,
	sinceEventId?: string,
	opts: { excludeEventTypes?: Set<string> } = {},
): Promise<number> {
	const file = join(eventsDir(), `${sessionId}.jsonl`);
	if (!existsSync(file)) return 0;
	const text = await readFile(file, "utf8");
	let n = 0;
	for (const line of text.split("\n")) {
		if (!line) continue;
		try {
			const e = JSON.parse(line) as { event_id?: string; event_type?: string };
			if (opts.excludeEventTypes && e.event_type && opts.excludeEventTypes.has(e.event_type)) continue;
			if (sinceEventId) {
				if (e.event_id && e.event_id > sinceEventId) n += 1;
			} else {
				n += 1;
			}
		} catch {
			// torn write
		}
	}
	return n;
}

async function maybeEnqueueDream(sessionId: string): Promise<boolean> {
	// Write dream-pending whenever >=1 meaningful new event exists since the
	// watermark for this session. "Stop" events are excluded — they are session
	// housekeeping, not durable work. Time/session gates live in runner.ts.
	const { readWatermark } = await import("./store.ts");
	const wm = await readWatermark();
	const sinceEventId = wm[sessionId];
	const count = await eventsSinceFor(sessionId, sinceEventId, { excludeEventTypes: new Set(["Stop"]) });
	const inboxBytes = await inboxSizeBytes();
	const eventsTrigger = count >= 1;
	const inboxTrigger = inboxBytes >= DREAM_INBOX_BYTES_THRESHOLD;
	if (!eventsTrigger && !inboxTrigger) return false;
	const marker = join(eventsRoot(), "dream-pending");
	await mkdir(eventsRoot(), { recursive: true });
	await writeFile(
		marker,
		JSON.stringify({
			at: new Date().toISOString(),
			sessionId,
			count,
			inbox_bytes: inboxBytes,
			reason: eventsTrigger
				? (inboxTrigger ? "events+inbox" : "events")
				: "inbox",
		}) + "\n",
	);
	return true;
}

// ---------------------------------------------------------------------------
// Per-event dispatch.

export type DispatchResult = {
	stdout: string;
	timedOut: boolean;
	enqueuedDream?: boolean;
	recall?: {
		bytes: number;
		latency_ms?: number;
		qmd?: {
			state: "ok" | "timeout" | "unhealthy" | "error" | "skipped";
			hits: number;
			permalinks: string[];
		};
		inbox_hits?: number;
		inbox_preview?: string[];
	};
};

export async function dispatchSessionStart(hook: NormalisedHook): Promise<DispatchResult> {
	const slug = await resolveProjectSlug(hook.cwd);
	const started = Date.now();
	// CACHE CRITICAL: this dispatcher returns only the per-cwd persistent
	// memory — project/<slug>/MEMORY.md. The stable, global profile/** snapshot
	// is injected separately via the extension's systemPrompt:build filter so it
	// joins the cross-cwd cacheable base instead of the per-cwd tail. Never
	// inject inbox/raw capture here: it carries event ids and timestamps that
	// change between sessions.
	//
	// DETERMINISM (no timeout): loadProjectContext is a single local readFile
	// (readIndexFile → MEMORY.md) — no subprocess, no network, sub-millisecond.
	// The old wall-clock race made the first-turn bytes nondeterministic (a fast
	// session got the full file, a cold one timed out to ""), bursting the
	// cross-session prompt cache for this cwd. Claude Code loads CLAUDE.md the
	// same way — a plain file read. Regression: test/session-start.test.ts.
	const { content, files } = await loadProjectContext(slug, {
		maxBytes: SESSION_START_MAX_BYTES,
		maxFiles: SESSION_START_MAX_FILES,
	});
	const bytes = Buffer.byteLength(content, "utf8");
	void appendEvent({
		sessionId: hook.sessionId,
		client: hook.client,
		cwd: hook.cwd,
		projectSlug: slug,
		eventType: "RecallInjected",
		payload: {
			where: "SessionStart",
			bytes,
			latency_ms: Date.now() - started,
			files: files.length,
			qmd: { state: "skipped", hits: 0, permalinks: [] },
		},
	});
	void getHCTel().then(({ withSpan }) => withSpan("dispatch.sessionStart", {
		bytes_returned: bytes,
		files_returned: files.length,
	}, async () => {}));
	return { stdout: content, timedOut: false };
}

export async function dispatchUserPromptSubmit(hook: NormalisedHook): Promise<DispatchResult> {
	const slug = await resolveProjectSlug(hook.cwd);
	const query = typeof hook.payload.prompt === "string" ? hook.payload.prompt : "";

	// P3-ISSUE-1 fix: persist the prompt itself before doing recall, so the
	// dream consolidation phase can see what the user actually asked. Previous
	// behaviour appended only MemoryInjectionTimeout / nothing, which made
	// `dream events tail` blind to user intent inside Pi sessions.
	// Fire-and-forget — we never want event-log latency to block the agent
	// loop, and the redaction layer + payload_hash live in appendEvent itself.
	void appendEvent({
		sessionId: hook.sessionId,
		client: hook.client,
		cwd: hook.cwd,
		projectSlug: slug,
		eventType: "UserPromptSubmit",
		payload: { prompt: query, ...(hook.payload.first_turn ? { first_turn: true } : {}) },
	});

	if (!query.trim()) return { stdout: "", timedOut: false };
	try {
		const started = Date.now();
		// Two recall sources in parallel under the SAME budget:
		//   - qmd (canonical wiki, vector + BM25)
		//   - inbox (raw same-session capture; no qmd dependency — fixes
		//     the latency cliff that motivated this whole change)
		// Either, both, or none may produce hits. We never let one tool's
		// failure or absence suppress the other.
		const [qmd, inboxEntries] = await withTimeout(
			Promise.all([
				searchMemory(query, userPromptQmdSearchOptions()),
				readInbox().then((all) => searchInbox(all, query, USER_PROMPT_INBOX_TOP_N))
					.catch(() => [] as InboxEntry[]),
			]),
			USER_PROMPT_SEARCH_MS + 50,
			"UserPromptSubmit search",
		);
		const latency_ms = Date.now() - started;
		const anyTimedOut = qmd.timedOut;
		const qmdShortCircuit = isQmdUnhealthyError(qmd.error);
		if (anyTimedOut && !qmdShortCircuit) {
			void appendEvent({
				sessionId: hook.sessionId,
				client: hook.client,
				cwd: hook.cwd,
				projectSlug: slug,
				eventType: "MemoryInjectionTimeout",
				payload: {
					where: "UserPromptSubmit",
					budget_ms: USER_PROMPT_SEARCH_MS,
					qmd_timed_out: qmd.timedOut,
				},
			});
		}
		// Render inbox first (raw, freshest) then ranked merged hits below.
		const inboxBlock = renderInboxBlock(inboxEntries, USER_PROMPT_INBOX_MAX_BYTES);
		const inboxBytes = Buffer.byteLength(inboxBlock, "utf8");
		const remainingBytes = Math.max(0, USER_PROMPT_MAX_BYTES - inboxBytes - (inboxBlock ? 2 : 0));
		const rankedStdout = mergeRecallBlocks(
			[{ heading: "qmd notes", hits: qmd.results.slice(0, USER_PROMPT_TOP_N) }],
			remainingBytes,
		);
		const stdout = [inboxBlock, rankedStdout].filter(Boolean).join("\n\n");
		const recall = stdout
			? {
					bytes: Buffer.byteLength(stdout, "utf8"),
					latency_ms,
					qmd: {
						state: qmd.timedOut ? "timeout" as const : qmdShortCircuit ? "unhealthy" as const : qmd.error ? "error" as const : "ok" as const,
						hits: qmd.results.length,
						permalinks: qmd.results.slice(0, USER_PROMPT_TOP_N).map((h) => h.permalink),
					},
					inbox_hits: inboxEntries.length,
					inbox_preview: inboxEntries.slice(0, USER_PROMPT_INBOX_TOP_N).map((e) => previewText(e.text)),
				}
			: undefined;
		// Fire-and-forget RecallInjected — records what was actually injected
		// so `dream recall watch` and `dream recall last` have real data.
		if (stdout && recall) {
			void appendEvent({
				sessionId: hook.sessionId,
				client: hook.client,
				cwd: hook.cwd,
				projectSlug: slug,
				eventType: "RecallInjected",
				payload: {
					where: "UserPromptSubmit",
					...recall,
				},
			});
		}

		// Telemetry: counters always recorded (D5), span at 10% head-sampling.
		void getHCTel().then(({ recordCounter, recordHistogram, withSpan }) => {
			recordCounter("dream_memory.recall.hits", qmd.results.length, { source: "qmd" });
			recordCounter("dream_memory.recall.hits", inboxEntries.length, { source: "inbox" });
			recordHistogram("dream_memory.recall.latency_ms", latency_ms, { source: "qmd" });
			if (Math.random() < 0.1) {
				void withSpan("dispatch.userPromptSubmit", {
					prompt_chars: query.length,
					inbox_hits: inboxEntries.length,
					qmd_hits: qmd.results.length,
				}, async () => {});
			}
		});

		return { stdout, timedOut: anyTimedOut, ...(recall ? { recall } : {}) };
	} catch (err) {
		if (err instanceof TimeoutError) {
			void appendEvent({
				sessionId: hook.sessionId,
				client: hook.client,
				cwd: hook.cwd,
				projectSlug: slug,
				eventType: "MemoryInjectionTimeout",
				payload: { where: "UserPromptSubmit", budget_ms: USER_PROMPT_SEARCH_MS },
			});
			return { stdout: "", timedOut: true };
		}
		throw err;
	}
}

/** Collapse whitespace and truncate to a short single-line preview for UI notifications. */
export function previewText(text: string, max = 32): string {
	const flat = text.replace(/\s+/g, " ").trim();
	return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat;
}

/**
 * Render up to maxBytes of inbox entries as a `## inbox (inbox)` block.
 * Newest-first within the input order. Returns "" if no entries fit.
 */
export function renderInboxBlock(entries: InboxEntry[], maxBytes: number): string {
	if (entries.length === 0 || maxBytes <= 0) return "";
	const header = `## inbox (inbox)`;
	let bytes = Buffer.byteLength(header, "utf8");
	const parts: string[] = [header];
	for (const e of entries) {
		const block = `### ${e.event_id}  · ${e.ts}\n\n${e.text}`;
		const sep = 2;
		const sz = Buffer.byteLength(block, "utf8");
		if (bytes + sep + sz > maxBytes) break;
		parts.push(block);
		bytes += sep + sz;
	}
	return parts.length > 1 ? parts.join("\n\n") : "";
}

/**
 * Merge ranked hit lists into one `<recalled-memory>`-ready string.
 * Round-robin so no source can starve the others if several produce hits;
 * each hit gets a `## <heading>` group header the first time it appears.
 * Stops as soon as the next block would exceed `maxBytes`.
 */
export function mergeRecallBlocks(
	blocks: Array<{ heading: string; hits: SearchHit[] }>,
	maxBytes: number,
): string {
	const sources = blocks.map((b) => ({ heading: b.heading, hits: b.hits, idx: 0, emitted: false }));
	const out: string[] = [];
	let bytes = 0;
	let remaining = sources.reduce((n, s) => n + s.hits.length, 0);
	while (remaining > 0) {
		let progressed = false;
		for (const s of sources) {
			if (s.idx >= s.hits.length) continue;
			const hit = s.hits[s.idx]!;
			const body = hit.matched_chunk ?? hit.content ?? "";
			const pieces: string[] = [];
			if (!s.emitted) pieces.push(`## ${s.heading}`);
			pieces.push(`### ${hit.permalink}\n\n${body}`);
			const block = pieces.join("\n\n");
			const sep = out.length ? 2 : 0;
			const sz = Buffer.byteLength(block, "utf8");
			if (bytes + sep + sz > maxBytes) {
				remaining = 0;
				break;
			}
			out.push(block);
			bytes += sep + sz;
			s.idx++;
			s.emitted = true;
			remaining--;
			progressed = true;
		}
		if (!progressed) break;
	}
	return out.join("\n\n");
}

export async function dispatchToolEvent(hook: NormalisedHook): Promise<DispatchResult> {
	const slug = await resolveProjectSlug(hook.cwd);
	await appendEvent({
		sessionId: hook.sessionId,
		client: hook.client,
		cwd: hook.cwd,
		projectSlug: slug,
		eventType: hook.eventType,
		payload: hook.payload,
	});
	return { stdout: "", timedOut: false };
}

export async function dispatchStop(hook: NormalisedHook): Promise<DispatchResult> {
	const slug = await resolveProjectSlug(hook.cwd);
	await appendEvent({
		sessionId: hook.sessionId,
		client: hook.client,
		cwd: hook.cwd,
		projectSlug: slug,
		eventType: "Stop",
		payload: hook.payload,
	});
	const enqueued = await maybeEnqueueDream(hook.sessionId);
	return { stdout: "", timedOut: false, enqueuedDream: enqueued };
}

// ---------------------------------------------------------------------------
// Top-level dispatcher with the 200ms wall budget.

export async function dispatch(hook: NormalisedHook): Promise<DispatchResult> {
	const handler = (() => {
		switch (hook.eventType) {
			case "SessionStart":
				return dispatchSessionStart(hook);
			case "UserPromptSubmit":
				return dispatchUserPromptSubmit(hook);
			case "PreToolUse":
			case "PostToolUse":
				return dispatchToolEvent(hook);
			case "Stop":
				return dispatchStop(hook);
			default:
				return dispatchToolEvent(hook); // unknown → just log
		}
	})();
	try {
		return await withTimeout(handler, TOTAL_WALL_BUDGET_MS, `${hook.eventType} total`);
	} catch (err) {
		if (err instanceof TimeoutError) {
			// Best-effort breadcrumb. Don't await — we're already over budget.
			void (async () => {
				try {
					const slug = await resolveProjectSlug(hook.cwd);
					await appendEvent({
						sessionId: hook.sessionId,
						client: hook.client,
						cwd: hook.cwd,
						projectSlug: slug,
						eventType: "MemoryInjectionTimeout",
						payload: { where: hook.eventType, budget_ms: TOTAL_WALL_BUDGET_MS },
					});
				} catch {
					// swallow — we already missed the budget
				}
			})();
			return { stdout: "", timedOut: true };
		}
		throw err;
	}
}

// ---------------------------------------------------------------------------
// main()

export async function main(argv = process.argv.slice(2)): Promise<number> {
	let parsed: ReturnType<typeof parseArgs>;
	try {
		parsed = parseArgs(argv);
	} catch (err) {
		console.error(`[harness-cli] ${(err as Error).message}`);
		return 2;
	}
	let raw: unknown;
	try {
		const text = await readStdin();
		if (!text.trim()) {
			console.error("[harness-cli] empty stdin; expected hook JSON payload");
			return 2;
		}
		raw = JSON.parse(text);
	} catch (err) {
		console.error(`[harness-cli] bad stdin JSON: ${(err as Error).message}`);
		return 2;
	}
	let hook: NormalisedHook;
	try {
		hook = normalise(parsed.client, raw);
	} catch (err) {
		console.error(`[harness-cli] normalise failed: ${(err as Error).message}`);
		return 2;
	}
	try {
		const r = await dispatch(hook);
		if (r.stdout) process.stdout.write(r.stdout);
		return 0;
	} catch (err) {
		// Programmer error past every guard. Log + non-zero.
		console.error(`[harness-cli] dispatch crashed: ${(err as Error).stack ?? String(err)}`);
		return 1;
	}
}

const isEntry = (() => {
	try {
		const url = new URL(import.meta.url);
		return url.pathname === process.argv[1] || url.pathname.endsWith(process.argv[1] ?? "");
	} catch {
		return false;
	}
})();
if (isEntry) {
	main()
		.then((code) => process.exit(code))
		.catch((err) => {
			console.error(err);
			process.exit(1);
		});
}

