	if (!resolved) {
		resolved = normaliseSlug(basename(absCwd));
	}
	if (!SLUG_RE.test(resolved)) {
		throw new Error(`resolveProjectSlug: invalid slug "${resolved}" for ${absCwd}`);
	}

	// Persist + check for mismatch. Anchor under the git root if available so
