	const gitDir = await findUp(absCwd, ".git");
	const anchor = gitDir ? dirname(gitDir) : absCwd;
	const map = await readSlugMap();
	const recorded = map[anchor];
	if (recorded && recorded !== resolved) {
		throw new ProjectSlugMismatchError(anchor, resolved, recorded);
	}
	if (!recorded) {
		map[anchor] = resolved;
		await writeSlugMap(map);
	}
	return resolved;
}

// ---------------------------------------------------------------------------
// Convenience helpers used by extension.ts / harness-cli.ts (deliverables 3+5)

// Index-only auto-inject (mirrors Claude Code's memdir.ts ENTRYPOINT_NAME).
// Topic files under profile/ and project/<slug>/ are NOT auto-loaded — they
// are discovered via memory_search and read on demand. MEMORY.md is the
// progressive-disclosure index.
const INDEX_FILE = "MEMORY.md";

async function readIndexFile(
	relParts: string[],
	opts: ReadMemoryOptions = {},
): Promise<{ content: string; files: string[]; truncated: boolean }> {
	const base = memoryDir();
	const rel = join(...relParts);
	try {
		const body = stripLeadingFrontmatter(await readFile(join(base, rel), "utf8")).trim();
		const content = `### ${rel}\n\n${body}`;
		if (Buffer.byteLength(content, "utf8") > (opts.maxBytes ?? DEFAULT_MAX_BYTES)) {
			return { content: "", files: [], truncated: true };
		}
		return { content, files: [rel], truncated: false };
	} catch {
		return { content: "", files: [], truncated: false };
	}
}

function stripLeadingFrontmatter(body: string): string {
	return body.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, "");
}

export async function loadProfileContext(opts?: ReadMemoryOptions) {
	return readIndexFile(["profile", INDEX_FILE], opts);
}

export async function loadProjectContext(slug: string, opts?: ReadMemoryOptions) {
	return readIndexFile(["project", slug, INDEX_FILE], opts);
}

// Back-compat path bag for any caller that still references constants.
export const paths = {
	get EVENTS_ROOT() {
		return eventsRoot();
	},
	get EVENTS_DIR() {
		return eventsDir();
	},
	get MEMORY_DIR() {
		return memoryDir();
	},
};

