describe("dispatchSessionStart — deterministic project memory (no timeout race)", () => {
	it("returns only the VOLATILE project MEMORY.md index — profile rides the cacheable base", async () => {
		// Indexes are auto-injected. Profile is NOT in this stdout anymore: the
		// stable global profile snapshot is injected separately via the
		// extension's systemPrompt:build filter so it joins the cross-cwd base.
		await writeFile(join(memoryDir(), "profile", "MEMORY.md"), "# Profile index\n- [p1](p1.md) — bit\n");
		await writeFile(join(memoryDir(), "project", "demo", "MEMORY.md"), "# Demo index\n- [arch](arch.md) — overview\n");
		// Topic files exist but are NOT auto-loaded — progressive disclosure.
		await writeFile(join(memoryDir(), "profile", "p1.md"), "# Profile topic bit\n");
		await writeFile(join(memoryDir(), "project", "demo", "arch.md"), "# Demo arch topic\n");
		const r = await dispatchSessionStart({
			client: "claude",
			sessionId: "s1",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});
		expect(r.timedOut).toBe(false);
		expect(r.stdout).toContain("# Demo index");
		expect(r.stdout).not.toContain("# Profile index"); // moved to the base filter
		expect(r.stdout).not.toContain("# Profile topic bit");
		expect(r.stdout).not.toContain("# Demo arch topic");
		expect(Buffer.byteLength(r.stdout, "utf8")).toBeLessThanOrEqual(24 * 1024);
	});

	it("strips volatile frontmatter from SessionStart persistent memory", async () => {
		await writeFile(
			join(memoryDir(), "profile", "MEMORY.md"),
			[
				"---",
				"source_event_ids:",
				'  - "01HVOLATILE"',
				'last_dreamed_at: "2026-05-28T00:00:00.000Z"',
				"---",
				"# Profile index",
				"- Stable global memory.",
			].join("\n"),
		);
		await writeFile(
			join(memoryDir(), "project", "demo", "MEMORY.md"),
			[
				"---",
				'last_dreamed_at: "2026-05-29T00:00:00.000Z"',
				"---",
				"# Demo index",
				"- Stable project memory.",
			].join("\n"),
		);

		const first = await dispatchSessionStart({
			client: "pi",
			sessionId: "s-stable-1",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});
		const second = await dispatchSessionStart({
			client: "pi",
			sessionId: "s-stable-2",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});

		expect(first.stdout).toContain("# Demo index");
		expect(first.stdout).not.toContain("# Profile index"); // profile is base-injected now
		expect(first.stdout).not.toContain("source_event_ids");
		expect(first.stdout).not.toContain("last_dreamed_at");
		expect(first.stdout).not.toContain("---");
		expect(second.stdout).toBe(first.stdout);
	});

	it("does not inject inbox/raw capture into SessionStart persistent memory", async () => {
		await writeFile(join(memoryDir(), "project", "demo", "MEMORY.md"), "# Demo index\n- Stable project memory.\n");
		await appendInboxNote({
			event_id: "01HZZZ0000000000000000009Q",
			session_id: "sess-dynamic",
			slug: "demo",
			text: "raw dynamic note from a prior turn",
			ts: "2026-05-28T00:00:00.000Z",
		});

		const r = await dispatchSessionStart({
			client: "pi",
			sessionId: "s-no-inbox",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});

		expect(r.stdout).toContain("# Demo index");
		expect(r.stdout).not.toContain("inbox/notes.md");
		expect(r.stdout).not.toContain("raw dynamic note from a prior turn");
	});

	it("no timeout race: project MEMORY.md is always returned in full, never starved to empty", async () => {
		// REGRESSION (cross-session prompt cache): dispatchSessionStart used to
		// wrap the project read in withTimeout(150ms) and return "" on a slow
		// read. That made the first-turn <persistent-memory> bytes
		// nondeterministic — a fast session got the full file, a cold one got
		// empty — bursting the cross-session cache for the cwd. The read is now a
		// plain local readFile (no race), so even a large unrelated corpus can
		// never starve it: every session for a cwd gets byte-identical content.
