				dispatchSessionStart({
					client: "pi",
					sessionId: `s-race-${sid}`,
					cwd: join(scratch, "demo"),
					eventType: "SessionStart",
					payload: {},
				}),
			),
		);
		for (const r of runs) {
			expect(r.timedOut).toBe(false); // no timeout branch exists anymore
			expect(r.stdout).toContain("Stable project memory line."); // full content, never ""
			expect(Buffer.byteLength(r.stdout, "utf8")).toBeLessThanOrEqual(24 * 1024);
		}
		// Byte-identical across every session for this cwd → warm cross-session cache.
		const [first, ...rest] = runs.map((r) => r.stdout);
		for (const s of rest) expect(s).toBe(first);

