// that parse, so such content is NOT placed in the base — before_agent_start
// falls back to the tail (no content loss, just no cross-cwd cache).
function isProfileBaseSafe(content: string): boolean {
	return !content.includes("</project_instructions>") && !content.includes('<project_instructions path="');
}

type ProfileSnapshot = { block: string; content: string; safe: boolean };
let _profileSnapshot: ProfileSnapshot | null | undefined;

/** Load + memoise the stable profile snapshot. `null` = no profile content. */
async function getProfileSnapshot(): Promise<ProfileSnapshot | null> {
	if (_profileSnapshot !== undefined) return _profileSnapshot;
	try {
		const { content } = await loadProfileContext({
			maxBytes: SESSION_START_MAX_BYTES,
			maxFiles: SESSION_START_MAX_FILES,
		});
		const trimmed = content.trim();
		if (!trimmed) {
			_profileSnapshot = null;
			return null;
		}
		_profileSnapshot = {
			block: `${PROFILE_BLOCK_OPEN}\n${trimmed}\n</project_instructions>`,
			content: trimmed,
			safe: isProfileBaseSafe(trimmed),
		};
	} catch {
		_profileSnapshot = null;
	}
	return _profileSnapshot;
}

// True once the filter has placed profile in the system prompt this build, so
// before_agent_start does not also add it to the volatile tail (no dup).
let profilePlacedInBase = false;

/**
 * Insert the profile block as the first <project_instructions> block inside
 * <project_context>, leading cache-base-prompt's contiguous global run.
 * Returns the input unchanged when profile is already present (idempotent), or
 * `null` when there is no <project_context> to splice into.
 */
export function injectProfileBlock(prompt: string, block: string): string | null {
	if (typeof prompt !== "string") return null;
	if (prompt.includes(PROFILE_BLOCK_OPEN)) return prompt; // idempotent
	const pcOpen = prompt.indexOf(PC_OPEN_TAG);
	if (pcOpen === -1) return null;
	const firstBlock = prompt.indexOf('<project_instructions path="', pcOpen);
	const at = firstBlock !== -1 ? firstBlock : pcOpen + PC_OPEN_TAG.length + 1;
	return `${prompt.slice(0, at)}${block}\n\n${prompt.slice(at)}`;
}

