			const fallbackProfile = !profilePlacedInBase && snap?.content ? snap.content : "";
			const tail = [fallbackProfile, sess.stdout].filter(Boolean).join("\n\n");
			if (!tail) return undefined;
			return {
				systemPrompt: `${event.systemPrompt}\n\n<persistent-memory>\n${tail}\n</persistent-memory>`,
			};
		}

		// Subsequent turns: prefetch recall, optionally wait briefly for
		// lookup-style prompts, and let the context hook deliver it at the tail
		// of the per-call model context.
		ensurePassiveRecall(event.prompt, ctx, cfg);
		lastCfg = cfg;
		ensureRecallPrefetch(event.prompt, ctx, cfg);
		if (shouldAwaitActiveRecall(event.prompt)) {
			await waitForRecallPreflight(pendingRecall);
		}
		return undefined;
	},
);

