export async function dispatchSessionStart(hook: NormalisedHook): Promise<DispatchResult> {
	const slug = await resolveProjectSlug(hook.cwd);
	const started = Date.now();
	// CACHE CRITICAL: this dispatcher returns only the per-cwd persistent
	// memory — project/<slug>/MEMORY.md. The stable, global profile/** snapshot
	// is injected separately via the extension's systemPrompt:build filter so it
	// joins the cross-cwd cacheable base instead of the per-cwd tail. Never
	// inject inbox/raw capture here: it carries event ids and timestamps that
	// change between sessions.
	//
	// DETERMINISM (no timeout): loadProjectContext is a single local readFile
	// (readIndexFile → MEMORY.md) — no subprocess, no network, sub-millisecond.
	// The old wall-clock race made the first-turn bytes nondeterministic (a fast
	// session got the full file, a cold one timed out to ""), bursting the
	// cross-session prompt cache for this cwd. Claude Code loads CLAUDE.md the
	// same way — a plain file read. Regression: test/session-start.test.ts.
	const { content, files } = await loadProjectContext(slug, {
		maxBytes: SESSION_START_MAX_BYTES,
		maxFiles: SESSION_START_MAX_FILES,
	});
	const bytes = Buffer.byteLength(content, "utf8");
	void appendEvent({
		sessionId: hook.sessionId,
		client: hook.client,
		cwd: hook.cwd,
		projectSlug: slug,
		eventType: "RecallInjected",
		payload: {
			where: "SessionStart",
			bytes,
			latency_ms: Date.now() - started,
			files: files.length,
			qmd: { state: "skipped", hits: 0, permalinks: [] },
		},
	});
	void getHCTel().then(({ withSpan }) => withSpan("dispatch.sessionStart", {
		bytes_returned: bytes,
		files_returned: files.length,
	}, async () => {}));
	return { stdout: content, timedOut: false };
}

