async function seed(profileCount: number, projectCount: number, bytesPerNote = 512): Promise<void> {
	const body = "x".repeat(bytesPerNote);
	const writes: Promise<unknown>[] = [];
	for (let i = 0; i < profileCount; i++) {
		writes.push(writeFile(join(memoryDir(), "profile", `p-${String(i).padStart(4, "0")}.md`), `# p${i}\n${body}\n`));
	}
	for (let i = 0; i < projectCount; i++) {
		writes.push(writeFile(join(memoryDir(), "project", "demo", `d-${String(i).padStart(4, "0")}.md`), `# d${i}\n${body}\n`));
	}
	await Promise.all(writes);
}

async function timed(): Promise<{ wallMs: number; bytes: number; truncated: boolean; files: number }> {
	const t0 = performance.now();
	const r = await dispatchSessionStart({
		client: "pi",
		sessionId: "perf-session",
		cwd: join(scratch, "demo"),
		eventType: "SessionStart",
		payload: {},
	});
	const wallMs = performance.now() - t0;
	const bytes = Buffer.byteLength(r.stdout, "utf8");
	// truncated isn't returned by dispatchSessionStart, infer from the cap.
	return { wallMs, bytes, truncated: bytes >= SESSION_START_MAX_BYTES - 1024, files: 0 };
}

describe("perf — SessionStart injection budgets", () => {
	for (const [profileN, projectN, label] of [
		[5, 5, "10 notes (small vault)"],
		[50, 50, "100 notes (medium vault)"],
		[500, 500, "1000 notes (large vault)"],
	] as const) {
		it(`${label}: wall <= ${SESSION_START_WALL_BUDGET_MS}ms AND bytes <= ${SESSION_START_MAX_BYTES}`, async () => {
			await seed(profileN, projectN);
			// Warm-up read once (fs/dirent caching) so the assertion measures
			// steady-state, not the first cold walk.
			await timed();
			const { wallMs, bytes } = await timed();
			expect(bytes).toBeLessThanOrEqual(SESSION_START_MAX_BYTES);
			expect(wallMs).toBeLessThanOrEqual(SESSION_START_WALL_BUDGET_MS);
		}, 5_000);
	}

	it("returns at most 8 files even when 100s are present", async () => {
		await seed(200, 0, 64);
		const r = await dispatchSessionStart({
			client: "pi",
			sessionId: "perf-cap",
			cwd: join(scratch, "demo"),
			eventType: "SessionStart",
			payload: {},
		});
		// Each block starts with `### path\n\n` — count the headers.
		const headers = (r.stdout.match(/^### /gm) ?? []).length;
		expect(headers).toBeLessThanOrEqual(8);
	});
});

