// The old wall-clock race made the first-turn bytes nondeterministic (a fast
// session got the full file, a cold one timed out to ""), bursting the
// cross-session prompt cache for this cwd. Claude Code loads CLAUDE.md the
// same way — a plain file read. Regression: tests/harness-cli.spec.ts +
// tests/cross-harness-smoke.spec.ts.
const includeProfile = hook.client !== "pi";
const profile = includeProfile
	? await loadProfileContext({ maxBytes: SESSION_START_MAX_BYTES, maxFiles: SESSION_START_MAX_FILES })
	: { content: "", files: [] as string[] };
const remainingBytes = Math.max(0, SESSION_START_MAX_BYTES - Buffer.byteLength(profile.content, "utf8"));
const remainingFiles = Math.max(0, SESSION_START_MAX_FILES - profile.files.length);
const project = remainingBytes > 0 && remainingFiles > 0
	? await loadProjectContext(slug, { maxBytes: remainingBytes, maxFiles: remainingFiles })
	: { content: "", files: [] as string[] };
const content = [profile.content, project.content].filter(Boolean).join("\n\n");
const files = [...profile.files, ...project.files];
const bytes = Buffer.byteLength(content, "utf8");

