// --- session_start ------------------------------------------------------
// Notification only per extensions.md §Session Events. We use it to log
// a SessionStart event so the dream phase can see when the session began;
// no return value participates in the agent loop.
pi.on("session_start", async (event: SessionStartEvent, ctx) => {
	if (isDreamMemoryDisabled()) {
		ctx.ui?.setStatus("dream-memory", ctx.ui.theme.fg("dim", "🧠 off"));
		return;
	}
	await dispatchToolEvent(
		baseHook("SessionStart", ctx, {
			reason: event.reason,
			...(event.previousSessionFile ? { previous_session_file: event.previousSessionFile } : {}),
		}),
	);
	// Set initial footer indicator.
	const cfg = await loadRecallConfig();
	const breaker = await readBreakerState();
	updateFooter(ctx, cfg.enabled, cfg.show_ui, isBreakerOpen(breaker, cfg, Date.now()));
});

function compactRecallQueryContext(text: string, maxChars = 600): string {
	const compact = text.replace(/[\u0000-\u001f\u007f]+/g, " ").replace(/\s+/g, " ").trim();
	return compact.length > maxChars ? compact.slice(0, maxChars).trimEnd() : compact;
}

/**
 * Extract the last N conversation turns as a compact one-line context string for active recall.
 * Kept short so QMD receives query signal, not a giant markdown transcript.
 */
function extractPriorContext(ctx: ExtensionContext | undefined, n: number): string | undefined {
	if (!ctx || n <= 0) return undefined;
	try {
		const entries = ctx.sessionManager.getEntries();
		// Collect the last N user/assistant messages, most-recent first.
		const msgs: string[] = [];
		for (let i = entries.length - 1; i >= 0 && msgs.length < n; i--) {
			const e = entries[i];
			if (!e) continue;
			if (e.type !== "message") continue;
			const msg = (e as { type: "message"; message: { role: string; content: unknown } }).message;
			if (msg.role !== "user" && msg.role !== "assistant") continue;
			const text = typeof msg.content === "string"
				? msg.content
				: Array.isArray(msg.content)

