/**
 * Drop the process-lifetime profile memo so the next getProfileSnapshot() call
 * re-reads profile/MEMORY.md from disk. Called on session_start: a background
 * dream run may have rewritten the profile since the previous session in this
 * process, and the contract is that a NEW session picks up changed memory by
 * content. Within a session the snapshot stays memoised (byte-stable across the
 * systemPrompt:build filter and the before_agent_start fallback); sub-agents do
 * not fire session_start, so they inherit the parent's stable snapshot.
 */
function resetProfileSnapshot(): void {
	_profileSnapshot = undefined;
	profilePlacedInBase = false;
}

