export async function dispatchSessionStart(hook: NormalisedHook): Promise<DispatchResult> {
	const slug = await resolveProjectSlug(hook.cwd);
	const started = Date.now();
	// Auto-inject contract (store.ts a0f290f): SessionStart surfaces the
	// progressive-disclosure indexes — profile/MEMORY.md (global preferences)
	// and project/<slug>/MEMORY.md (per-cwd decisions). Both must reach the
	// agent on every harness; topic files are discovered via memory_search.
	//
	// CACHE-CRITICAL split by client. Pi injects the stable global profile into
	// its cross-cwd cacheable base via the extension's systemPrompt:build filter
	// (and before_agent_start owns the tail fallback when the filter can't place
	// it), so the Pi dispatcher returns project memory ONLY — emitting profile
	// here would double-inject and burst Pi's prompt cache. Claude Code and Codex
	// have no such filter: this CLI dispatcher is their ONLY injection channel, so
	// the profile index must ride along in their stdout (profile first, then
	// project within the shared byte/file budget). Never inject inbox/raw capture
	// here: it carries event ids and timestamps that change between sessions.
	//
	// DETERMINISM (no timeout): each load is a single local readFile
	// (readIndexFile → MEMORY.md) — no subprocess, no network, sub-millisecond.
	// The old wall-clock race made the first-turn bytes nondeterministic (a fast
	// session got the full file, a cold one timed out to ""), bursting the
	// cross-session prompt cache for this cwd. Claude Code loads CLAUDE.md the
	// same way — a plain file read. Regression: tests/harness-cli.spec.ts +
	// tests/cross-harness-smoke.spec.ts.
	const includeProfile = hook.client !== "pi";
	const profile = includeProfile
		? await loadProfileContext({ maxBytes: SESSION_START_MAX_BYTES, maxFiles: SESSION_START_MAX_FILES })
		: { content: "", files: [] as string[] };
	const remainingBytes = Math.max(0, SESSION_START_MAX_BYTES - Buffer.byteLength(profile.content, "utf8"));
	const remainingFiles = Math.max(0, SESSION_START_MAX_FILES - profile.files.length);
	const project = remainingBytes > 0 && remainingFiles > 0
		? await loadProjectContext(slug, { maxBytes: remainingBytes, maxFiles: remainingFiles })
		: { content: "", files: [] as string[] };
	const content = [profile.content, project.content].filter(Boolean).join("\n\n");
	const files = [...profile.files, ...project.files];
	const bytes = Buffer.byteLength(content, "utf8");
	void appendEvent({
		sessionId: hook.sessionId,
		client: hook.client,
		cwd: hook.cwd,
		projectSlug: slug,
		eventType: "RecallInjected",
		payload: {
			where: "SessionStart",
			bytes,
			latency_ms: Date.now() - started,
			files: files.length,
			qmd: { state: "skipped", hits: 0, permalinks: [] },
		},
	});
	void getHCTel().then(({ withSpan }) => withSpan("dispatch.sessionStart", {
		bytes_returned: bytes,
		files_returned: files.length,
	}, async () => {}));
